export const ILLUSTRATED_EXERCISES: IllustratedExercise[] = [{"slug":"ab-rollout-on-knees-with-barbell","title":"Ab Rollout on Knees with Barbell","idNum":"0286","type":"compound","primary":["abdominals"],"secondary":["lower back","shoulders"],"equipment":["barbell"],"steps":["This exercise works the abs and lower back and is the proper version of an “ab roller”. This version is performed on your knees.","Place a barbell on the floor in front of you.","Start by kneeling in front of the bar, grip the barbell with a shoulder with overhand grip.","With a slow controlled motion, roll the bar out so that your back is straight, bend your knees and keep your feet off the floor.","Keep your arms straight throughout the exercise.","Roll back up bring the bar under your shoulders and return to the starting position."]},{"slug":"ab-rollout-with-barbell","title":"Ab Rollout with Barbell","idNum":"0285","type":"compound","primary":["abdominals"],"secondary":["lower back","shoulders"],"equipment":["barbell"],"steps":["Place a barbell on the floor at your feet.","Bending at the waist, grip the barbell with a shoulder with overhand grip.","With a slow controlled motion, roll the bar out so that your back is straight.","Keep your arms straight throughout the exercise.","Roll back up raising your hips and butt as you return to the starting position.","Note: Practice raising your hips and butt as high as you can with this exercise."]},{"slug":"air-bike","title":"Air Bike","idNum":"0284","type":"compound","primary":["abdominals"],"secondary":[],"equipment":["body"],"steps":["This exercise works your abs by raising your arms to meet your legs. The movements are similar to riding a bike.","Lie on your back on a mat.","Place your hands on either side of your head (over your ears).","Raise your legs up, bending your knees and keeping your calves parallel to the floor.","Bring your left arm elbow up to meet your right knee, as if riding a bike.","Repeat with your right elbow and left knee.","Continue alternating sides.","Note: Move your arms across your chest, squeezing your abs as you move."]},{"slug":"alternating-biceps-curl-with-dumbbell","title":"Alternating Bicep Curl with Dumbbell","idNum":"0223","type":"isolation","primary":["biceps"],"secondary":["forearm"],"equipment":["dumbbell"],"steps":["Steps","Stand with your feet shoulder width apart, your knees slightly bent and your abs drawn in.","Grasp a dumbbell in each hand so your palms are facing up.","Extend your arms so they are at the sides of your body.","Keeping your elbows locked lift your left arm to your chest so that your forearm touches your bicep.","Lower your arm and repeat with your right arm.","Note: Do not swing your body as you perform this exercise."]},{"slug":"alternating-hammer-curl-with-dumbbell","title":"Alternating Hammer Curl with Dumbbell","idNum":"0213","type":"isolation","primary":["biceps"],"secondary":["forearm"],"equipment":["dumbbell"],"steps":["This exercise uses a hammering (up and down) motion to isolate the biceps.","Stand with our feet shoulder width apart, your knees slightly bent and your abs drawn in.","Grasp a dumbbell in each hand so your palms are facing each other.","Extend your arms so they are at the sides of your body.","Keeping your elbows locked lift your left arm in an arc towards your left shoulder.","Lower your arm and repeat with your right arm.","Note: Do not turn your wrists during this exercise."]},{"slug":"alternating-incline-curl-with-dumbbell","title":"Alternating Incline Curl with Dumbbell","idNum":"0214","type":"isolation","primary":["biceps"],"secondary":[],"equipment":["dumbbell"],"steps":["Adjust an incline bench to a 45 degree angle.","Grasp a dumbbell in each hand and sit back on the bench with your feet firmly planted on the floor.","Allow your arms to hang down at your sides.","Keeping your elbow straight, raise your right arm up towards your head.","In a controlled manner lower the weight and repeat with your left arm."]},{"slug":"ankle-circles","title":"Ankle Circles","idNum":"0270","type":"isolation","primary":["calves"],"secondary":[],"equipment":["body"],"steps":["Stand on one foot near a chair or wall for support.","Lift your foot off the ground and draw circles clockwise in the air with your toes.","Reverse the direction (counter-clockwise) as well as switch feet."]},{"slug":"back-extension-stability-ball","title":"Back Extension on Stability Ball","idNum":"0104","type":"isolation","primary":["lower back"],"secondary":["core","hamstrings"],"equipment":["exercise ball"],"steps":["Lie prone (on your stomach) on a Stability Ball with your toes firmly planted on the floor for balance.","With your hands across your chest or at your ears, raise your chest off the ball so you are hyperextending your spine.","Slowly return your chest to the ball.","Repeat."]},{"slug":"back-flys-exercise-band","title":"Back Fly's with Exercise Band","idNum":"0020","type":"isolation","primary":["shoulders"],"secondary":["triceps","middle back"],"equipment":["exercise band"],"steps":["Place an exercise band around a post or machine at mid chest height.","Stand with your feet shoulder width apart, abs drawn in and knees slightly bent.","Stand back from the post so there is tension in the band, grasping the band with your arms extended in front of you and a slight bend in your elbows; this is your starting position.","Bring your arms back in a controlled motion till they are parallel at your sides and in line with your shoulders.","Slowly return your arms to the starting position in front of your chest.","Repeat."]},{"slug":"ball-wall-circles","title":"Ball Wall Circles","idNum":"0019","type":"compound","primary":["shoulders"],"secondary":["biceps","triceps"],"equipment":["swiss ball"],"steps":["Stand upright with your feet shoulder width apart.","Place a Swiss ball at chest height against a wall and with your left hand, roll the ball in small circles against the wall.","Keep your arm fully extended with a slight bend in the elbow.","Reverse the direction of the circles.","Switch arms."]},{"slug":"barbell-dead-lifts","title":"Barbell Dead Lifts","idNum":"0099","type":"isolation","primary":["lower back"],"secondary":["hamstrings","calves"],"equipment":["barbell"],"steps":["Stand with your feet shoulder width apart so that your feet are under the bar.","Keeping your back straight bend at the waist, allow some bend in your knees.","Grasp the par with an overhand grip approximately 16 inches apart.","Straighten your back as you hold the bar at arm’s length.","Bend over again lowering the bar to just above the floor."]},{"slug":"barbell-front-raise-pullover","title":"Barbell Front Raise and Pullover","idNum":"0058","type":"isolation","primary":["chest"],"secondary":["triceps","shoulders"],"equipment":["barbell","flat bench"],"steps":["Lie on a flat bench and grasp a barbell using a medium grip (about 15” apart).","Place the barbell on your upper thighs and lock your arms straight with a slight bend in your elbows.","Draw your abs in and keeping your back flat on the bench, raise your arms up in an arc over and behind your head (as if you were performing a reverse pullover).","Slowly return the barbell to the starting position on your thighs."]},{"slug":"barbell-good-mornings","title":"Barbell Good Mornings","idNum":"0101","type":"isolation","primary":["lower back"],"secondary":["hamstrings"],"equipment":["barbell"],"steps":["Place a barbell across your shoulders.","Keeping your head up and your back completely straight, bend at the waist until your back is parallel with the floor.","Return to starting position.","Repeat."]},{"slug":"barbell-lunges","title":"Barbell Lunges","idNum":"0114","type":"isolation","primary":["hamstring"],"secondary":["gluts","quadriceps","calves"],"equipment":["barbell"],"steps":["Start by placing a barbell across your upper back, using a grip slightly wider than your shoulders.","Stand with your feet about 8 inches apart, toes facing forward.","Take a step forward (2-3 feet) keeping your abs drawn in and your upper body straight.","Slowly lower one knee down as if kneeling while keeping your other knee bent at a 90 degree angle, do not let your knee touch the ground.","Lower your body so that your rear knee is just above the floor and hold for a moment before returning to the starting position.","Repeat on other side."]},{"slug":"barbell-neck-press","title":"Barbell Neck Press","idNum":"0067","type":"isolation","primary":["chest"],"secondary":["biceps"],"equipment":["barbell","flat bench"],"steps":["Lie on a flat bench with you feet planted firmly on the floor.","Grasp the bar a little wider than shoulder width apart.","Raise the barbell above your body and move it to the top of your chest, near your neck.","This is your starting position.","Lower the bar down so it just touches the top of your chest.","Raise the bar till your arms are fully extended and your elbows are locked.","Return to starting position.","Repeat."]},{"slug":"barbell-shrugs","title":"Barbell Shrugs","idNum":"0030","type":"isolation","primary":["trapezius"],"secondary":[],"equipment":["barbell"],"steps":["Stand on the floor with your abs drawn in and your back straight.","Grasp a barbell with a grip a little wider than shoulder width at arms length.","Drop your shoulders as much as possible to start.","Raise your shoulder as high as possible.","Pause for a moment at the top and then return to starting position in a controlled motion.","Repeat."]},{"slug":"barbell-squat","title":"Barbell Squat","idNum":"0122","type":"compound","primary":["quadriceps"],"secondary":["hamstrings"],"equipment":["barbell"],"steps":["This is an exercise for leg strengthening, mainly the quadriceps.","Lifting a barbell off of a weight rack, position it on your shoulders.","Place your feet slightly wider than shoulder width apart with your knees and toes pointed slightly outward.","Drawing your abs in descend slowly by bending at the knees and hips as if you are sitting down (squatting).","Lower yourself as far as you can control without letting your body shift towards your toes (this will cause you to loose balance).","Pause in the downward position and slowly return upright to the starting position."]},{"slug":"bench-dips","title":"Bench Dips","idNum":"0162","type":"compound","primary":["triceps"],"secondary":["chest"],"equipment":["body"],"steps":["This exercise is one of the most basic and still one of the best for building the triceps (muscles on the back of the arm).","Place two benches parallel to each other 3-4 feet apart.","Sit on one bench and place your feet on the edge of the other bench so that your legs are suspended between the 2 benches.","Cross your feet for support.","Hold onto the bench with your hands for support and slowly lower body towards the floor by bending your elbows.","Pause and then return to starting position.","Note: Do not go below a 90 degree angle as this can cause on your shoulders."]},{"slug":"bench-press","title":"Bench Press","idNum":"0042","type":"compound","primary":["chest"],"secondary":["triceps"],"equipment":["bench","barbell"],"steps":["Lie on a flat bench with your feet flat on the floor, keep your back flat on the bench.","Grasp the bar a little wider than shoulder width apart.","Raise the barbell above your body and move it over the middle of your chest, this is your starting position.","Lower the bar down so it just touches your chest.","Raise the bar till your arms are fully extended and your elbows are locked.","Return to starting position."]},{"slug":"bench-press-dumbbell","title":"Bench Press Dumbbell","idNum":"0055","type":"isolation","primary":["chest"],"secondary":["shoulders","triceps"],"equipment":["dumbbells","flat bench"],"steps":["This is an exercise for chest, triceps and shoulder strengthening.","Grasp the dumbbells in each hand and lie on a flat bench with your feet firmly on the ground.","Extend your arms up over your chest with your palms facing forwards.","Press the dumbbells up over your chest till your arm are fully extended this is your starting position.","Bend your elbows to a 90 degree angle so your upper arms are parallel with the floor.","Slowly lower the dumbbells as low as comfortable along your chest.","With a controlled motion return back to your starting position.","Repeat."]},{"slug":"bent-arm-pullover","title":"Bent Arm Pullover","idNum":"0045","type":"isolation","primary":["chest"],"secondary":["lats","shoulders","triceps"],"equipment":["barbell","flat bench"],"steps":["Lie flat on a bench with your head hanging slightly over the end and your feet flat on the floor.","Hold a barbell with a close grip (approximately 14”), keep your elbows in throughout the exercise.","Starting with your arms fully extended over your chest, slowly lower the bar in an arc over your head and towards the floor.","Pull the bar back up to chest height in a slow controlled manner and return to starting position.","Repeat."]},{"slug":"bent-knee-hip-raise","title":"Bent Knee Hip Raise","idNum":"0287","type":"compound","primary":["abdominals"],"secondary":[],"equipment":["body"],"steps":["Lie on your back with your arms outstretched to your sides.","Bend your knees at a 60 degree angle and hold your feet up just off the floor.","Keeping your back and arms down, raise your hips up and off the floor so that your knees are over your chest.","Contract your abs for a moment and then return to the starting position."]},{"slug":"bent-over-rear-deltoid-raise-with-head-on-bench","title":"Bent Over Rear Deltoid Raise With Head On Bench","idNum":"0032","type":"isolation","primary":["shoulders"],"secondary":[],"equipment":["dumbbells"],"steps":["Rest your forehead on an incline bench in oder to stabilise your movements so you are bent over with your back parallel to the floor, draw your abs in.","Grasp dumbbells in your hands with your arms straight and elbows slightly bent ensuring they are not locked.","Slowly raise the dumbbells up to shoulder height.","Pause for a moment and then return to the starting position.","Repeat."]},{"slug":"bent-over-lateral-cable-raises","title":"Bent-over Lateral Cable Raises","idNum":"0017","type":"isolation","primary":["shoulders"],"secondary":["trapezius","middle back"],"equipment":["cable machine"],"steps":["Grasp the handle of the low pulley with your right hand.","Bend forward from the waist; your upper body should be nearly parallel with the floor. Bend your knees slightly and place your left hand on your left thigh. Let your right arm hang from your shoulder in front of you with your elbow slightly bent. This is your starting position.","Lift your right arm, keeping your elbow slightly bent.","Keep moving your arm until it is parallel to the floor, in line with your right ear.","Slowly bring the weight back down to the starting position.","Perform exercise on left arm and then repeat."]},{"slug":"bent-over-one-arm-triceps-extension-with-dumbbell","title":"Bent-Over One Arm Triceps Extension with Dumbbell","idNum":"0196","type":"isolation","primary":["triceps"],"secondary":[],"equipment":["dumbbell"],"steps":["Stand with your feet shoulder width apart, your abs drawn in and your back straight as you bend at the waist.","Hold a dumbbell in your right hand.","Bring your right arm up to your side so the dumbbell is almost parallel to your chest, keeping your lower arm vertical and press your arm back in arc.","Return to the starting position repeat and switch arms."]},{"slug":"bent-over-two-arm-triceps-extension-with-dumbbell","title":"Bent-Over Two Arm Triceps Extension with Dumbbell","idNum":"0197","type":"isolation","primary":["triceps"],"secondary":[],"equipment":["dumbbell"],"steps":["Stand with your feet shoulder width apart, your abs drawn in and your back straight as you bend at the waist until your upper body is parallel to the floor.","Hold a dumbbell in each hand.","Bring your right arm up to your side so the dumbbell in line with your chest, keeping your lower arm vertical and press your arm back in arc.","Return to the starting position repeat and switch arms."]},{"slug":"biceps-curl-lunge-with-bowling-motion","title":"Bicep Curl Lunge with Bowling Motion","idNum":"0262","type":null,"primary":["arms"],"secondary":["calves","triceps","hamstrings","glutes","quadriceps"],"equipment":["medicine ball"],"steps":["Hold a Medicine Ball in one hand with your palms facing up at shoulder height.","Bring one foot back and into a lunge, keeping your front foot stationary and not letting your back knee touch the ground.","While lunging, bring the ball down and back as if you were bowling.","Bring your arm back up to the starting position, switch legs and repeat.","Note: Use slow and steady movements with this exercies."]},{"slug":"biceps-curl-on-stability-ball-with-leg-raised","title":"Bicep Curl on Stability Ball with Leg Raised","idNum":"0263","type":"isolation","primary":["biceps"],"secondary":["hamstring","forearm","quadriceps","calves"],"equipment":["dumbbell"],"steps":["Grasp a dumbbell in each hand with a palms up grip.","Place the top of one foot behind you on a Stability Ball (see illustration) as if you were stretching your leg.","Keep your back straight and your abs drawn in.","Bring your arms down in front of your legs.","Raise your arms up, curling and contracting your biceps.","Lower your arms and return to starting position and switch legs."]},{"slug":"biceps-curl-with-deadlift-with-barbell","title":"Bicep Curl with Deadlift with Barbell","idNum":"0259","type":"isolation","primary":["biceps"],"secondary":["calves","lower back","hamstrings"],"equipment":["barbell"],"steps":["This is an advanced exercise. This exercise combines a bicep curl with a deadlift.","Grasp an EZ Curl or barbell with palms facing up.","Standing with your feet shoulder width apart and your knees slightly bent, draw your abs in.","Extend your arms so the bar rests in front of your thighs.","Bending at the waist, bring the bar down to just above the floor.","As you return to a standing position, bring the bar up and curl your arms bringing your forearms to your biceps.","Return the starting position and repeat.","Note: Performing this exercise in front of a mirror may help you spot and correct your form."]},{"slug":"biceps-curl-with-machine","title":"Bicep Curl with Machine","idNum":"0253","type":"isolation","primary":["biceps"],"secondary":["forearm"],"equipment":[],"steps":["Adjust the seat of the machine so your elbows are correctly aligned with the rotation axis.","Press your arms against the pads and keep them stationary throughout the exercise.","Curl your forearms until your arms are fully flexed.","Slowly lower your arms back to the starting position."]},{"slug":"biceps-curl-reverse-with-dumbbells","title":"Biceps Curl Reverse with Dumbbells","idNum":"0257","type":"isolation","primary":["biceps"],"secondary":["forearm"],"equipment":["dumbbell"],"steps":["Stand with your feet shoulder width apart, your knees slightly bent and your abs drawn in.","Grasp a dumbbell in each hand with palms facing down.","Keeping your arms at your side your elbows steady, lift the dumbbells up towards your shoulders.","Pause for a moment and then return to the starting position."]},{"slug":"biceps-curl-seated-on-stability-ball-with-dumbbell","title":"Biceps Curl Seated on Stability Ball with Dumbbell","idNum":"0255","type":"isolation","primary":["biceps"],"secondary":["forearm"],"equipment":["dumbbell"],"steps":["This version of a biceps curl uses a Stability Ball. Exercises preformed with Stability Balls encourage better posture and core muscle development.","Grasp a dumbbell in each hand while sitting on a Stability Ball with your feet placed firmly in front of you, and your abs drawn in.","Keeping your elbows at your side and your back straight, curl your arms up to your chest.","Pause for a moment, contracting your biceps.","Slowly lower your arms to the starting position."]},{"slug":"biceps-curl-squat-with-dumbbell","title":"Biceps Curl Squat with Dumbbell","idNum":"0256","type":"isolation, compound","primary":["biceps"],"secondary":["hamstrings","glutes"],"equipment":["dumbbell"],"steps":["This exercise combines a squat with a curl to effectively work the entire body. This is an advanced exercise.","Stand with your feet shoulder width apart, your knees slightly bent and your abs drawn in.","Grasp a dumbbell in each hand and curl your arms up to your shoulders.","Bending at the waist, squat down as you lower your hands to the floor (the lower part of a curl).","Pause for a moment and then return to the starting position.","Note: Contract your biceps as you curl your arms up."]},{"slug":"biceps-curl-v-sit-on-dome-with-dumbbells","title":"Biceps Curl V Sit on Dome with Dumbbells","idNum":"0269","type":"isolation","primary":["biceps"],"secondary":["abdominals","core"],"equipment":["dumbbell"],"steps":["This exercise uses a Dome (or Bosu) as a seat forcing you to engage and contract your abs throughout the exercise. The name comes from having our body in the shape of a “V”.","Grasp a dumbbell in each hand and sit on a dome.","Keep your legs together and your knees bent.","Draw in and hold your abs and keep your back straight.","With you arms extended to your sides, curl and contract your biceps, bringing your forearms towards your shoulders.","Slowly return to the starting position.","Note: Try to keep your balance steady and not move your legs throughout this exercise."]},{"slug":"biceps-curl-with-dumbbell","title":"Biceps Curl with Dumbbell","idNum":"0224","type":"isolation","primary":["biceps"],"secondary":["forearm"],"equipment":["dumbbell"],"steps":["Stand with our feet shoulder width apart, your knees slightly bent and your abs drawn in.","Grasp a dumbbell in each hand with your palms facing up.","Extend your arms so they are at the sides of your body.","Keeping your elbows, locked lift your arms to your chest so that your forearms touch your biceps.","In a slow controlled manner, lower your arms to the starting position.","Note: Do not swing your body as you perform this exercise."]},{"slug":"biceps-curl-with-overhead-extension-using-dumbbells-on-stability-ball","title":"Biceps Curl with Overhead Extension using Dumbbells on Stability Ball","idNum":"0260","type":"isolation","primary":["triceps","biceps"],"secondary":["forearm","should"],"equipment":["dumbbell"],"steps":["This is an advanced exercise. This exercise requires you to be able to balance kneeling on a stability ball before you can correctly perform this exercise.","Grasp a dumbbell in each hand with palms facing up.","Kneel on a Stability Ball, drawing your abs in and keeping your back straight.","Raise one arm up over your shoulder and keep your other arm curled.","Bend your raised arm back as if performing a triceps extension while lowering your other arm and curling it back.","Return to starting position and repeat arms.","Note: Work with a Personal Trainer or Instructor to learn how to safely perform this exercise."]},{"slug":"biceps-curls-with-barbell","title":"Biceps Curls with Barbell","idNum":"0211","type":"isolation","primary":["biceps"],"secondary":["shoulders","forearm"],"equipment":["barbell"],"steps":["This is a basic exercise for the biceps (arms).","Stand with your feet shoulder width apart, your knees slightly bent and your abs drawn in.","Grasp a barbell with palms facing up, approximately shoulder width apart.","Lower your arms fully to above your thighs and bending only your elbows, raise the bar to your upper chest.","Pause for a moment and then return to the starting position.","Note: Do not swing your hips or back during this exercise."]},{"slug":"biceps-hammer-curl-with-dumbbell","title":"Biceps Hammer Curl with Dumbbell","idNum":"0227","type":"isolation","primary":["biceps"],"secondary":[],"equipment":["dumbbell"],"steps":["This exercise uses a hammering (up and down) motion to isolate the biceps."," Stand with your feet shoulder width apart, your knees slightly bent and your abs drawn in.","Grasp a dumbbell in each hand so your palms are facing each other.","Extend your arms so they are at the sides of your body.","Keeping your elbows locked lift your arms in an arc towards your shoulders.","Lower your arms in a steady controlled motion and repeat.","Note: Do not turn your wrists during this exercise."]},{"slug":"body-leg-lifts","title":"Body Leg Lifts","idNum":"0111","type":"isolation","primary":["gluts"],"secondary":["hamstring"],"equipment":["body"],"steps":["Using a post or tall weight bench for balance stand straight with your abs drawn in.","Raise one off the ground and behind you while standing on the other leg.","Slowly lower the leg and raise it again while flexing the gluts.","Repeat with your other leg."]},{"slug":"body-row","title":"Body Row","idNum":"0086","type":"compound","primary":["chest"],"secondary":["core","neck","back"],"equipment":["bar"],"steps":["Lie under a bar so that the bar is at mid chest level and your feet are firmly on the floor.","Draw your abs in and keep your back flat.","Using your arms, lift and row your body towards the bar.","Pause for a moment and with slow controlled movements lower your self back to starting position.","Repeat."]},{"slug":"bosu-ball-push-up","title":"Bosu Ball Push Up","idNum":"0069","type":"isolation","primary":["chest"],"secondary":["shoulders","core","triceps"],"equipment":["bosu ball"],"steps":["Place the Bosu ball flat side down on the floor.","Kneel on the floor with your arms fully extended on the ball, and body straight.","Keeping your abs drawn in and your body straight, by bending your elbows lower your chest to the ball.","Pause for a moment and then return to starting position.","Repeat."]},{"slug":"bridging","title":"Bridging","idNum":"0109","type":"isolation","primary":["gluts"],"secondary":["core"],"equipment":["body"],"steps":["Lie on your back with your knees bent and your feet flat on the floor.","Lift up hips and bum off the floor as you draw your abs in and keep your gluts tight."]},{"slug":"cable-crossover","title":"Cable Crossover","idNum":"0048","type":"isolation","primary":["chest"],"secondary":["shoulders"],"equipment":["cable machine"],"steps":["Attach the cable pulley to shoulder height.","Grasp the pulley in both hands and stand approximately one foot in front of the weight stacks, with one foot slightly in front of the other.","With a slight bend in your elbows bring your hand together in front of your chest on downward angle.","When your hands meet at the midpoint of your chest, hold for a moment.","With a slow controlled motion return to starting position."]},{"slug":"cable-shoulder-shrugs","title":"Cable Shoulder Shrugs","idNum":"0009","type":"isolation","primary":["trapezius"],"secondary":["shoulders"],"equipment":["cable machine"],"steps":["Attach a pulley to the lowest setting on cable machine.","Stand with your feet shoulder width apart, your abs drawn and your back straight.","Start with the pulley at waist height.","Grasp the pulley and shrug your shoulders up while keeping your arms extended.","Hold this position for a moment then with a controlled motion return to the starting position of the pulley to waist height."]},{"slug":"calf-raises-with-band","title":"Calf Raises with Band","idNum":"0274","type":"isolation","primary":["calves"],"secondary":[],"equipment":["bands"],"steps":["This exercise uses a band to create resistance.","Stand with your toes on an exercise band and raise the handles up to your shoulders.","Raise up on your toes, keeping your hands up by your shoulders.","Pause for a moment and then lower your heel to the floor.","Repeat."]},{"slug":"calves-press-on-leg-machine","title":"Calves Press on Leg Machine","idNum":"0273","type":"isolation","primary":["calves"],"secondary":[],"equipment":["machine"],"steps":["This exercise uses a Leg Press Machine to work your calves. You can perform this exercise along with Leg Presses.","Sit down on a Leg Press Machine and press the plate up as if you were performing a leg press.","Slide your feet down so that the balls of your feet are pressing against the rack (with your heels hanging free).","Keeping the handles locked, press up and flex your toes and then slowly bring your toes back towards your body.","Perform theses movements slowly for maximum benefit.","Note: Use a lighter weight on this exercise than you are able to lift with a leg press until you are familiar with the movements."]},{"slug":"chest-dips","title":"Chest Dips","idNum":"0054","type":"isolation","primary":["chest"],"secondary":["triceps","shoulders"],"equipment":["body","parallel bars"],"steps":["Stand in between the parallel bars.","Grip the handles of the parallel bars and push yourself up to the starting position with straightened arms.","With your elbows close to your body keep your hips straight, lower your body forward by bending your elbows so your chest is leading as you go down.","Raise yourself back up to the starting position and repeat.","Repeat."]},{"slug":"close-grip-barbell-bench-press","title":"Close Grip Barbell Bench Press","idNum":"0049","type":"isolation","primary":["chest"],"secondary":["triceps","shoulders"],"equipment":["barbell"],"steps":["Lie on a flat bench with your feet flat on the floor, keep your back flat on the bench.","Grasp the bar a close grip (approximately 14” apart).","Raise the barbell above your body and move it over the middle of your chest, this is your starting position.","Lower the bar down so it just touches your chest.","Raise the bar till your arms are fully extended and your elbows are locked.","Return to starting position."]},{"slug":"close-grip-ez-bar-curl-with-barbell","title":"Close Grip EZ Bar Curl with Barbell","idNum":"0218","type":"isolation","primary":["biceps"],"secondary":["forearm"],"equipment":["barbell"],"steps":["Stand with your feet shoulder width apart, your knees slightly bent and your abs drawn in.","Grasp an EZ bar with an underhand close (4 inch) grip on the innermost part of the bar.","Extend your arms fully against your thighs.","Keeping your elbows straight, raise the bar towards your chest.","Pause for moment and then return to the starting position.","Note: Lean up against a wall or post if you have problems keeping from swinging."]},{"slug":"close-grip-standing-biceps-curls-with-barbell","title":"Close Grip Standing Biceps Curls with Barbell","idNum":"0219","type":"isolation","primary":["biceps"],"secondary":["forearm"],"equipment":["barbell"],"steps":["Stand with your feet shoulder width apart, your knees slightly bent and your abs drawn in.","Grasp a barbell with palms up, about 12 inches apart.","Extend your arms fully against your thighs.","Keeping your elbows straight, raise the bar towards your chest until your forearms touch your chest.","Pause for moment and then return to the starting position.","Note: Lean up against a wall or post if you have problems keeping from swinging."]},{"slug":"close-triceps-pushup","title":"Close Triceps Pushup","idNum":"0188","type":"compound","primary":["triceps"],"secondary":["chest"],"equipment":["body"],"steps":["This version of the Pushup isolates the tricep (back of the arm) muscles.","Kneel down on the floor or a mat, placing your hand thumbs together and raise your up on your toes.","Draw your abs in and keep your back and neck in a straight line.","Slowly lower your body towards the floor, by bending your arms, until you are nearly touching the floor.","In a controlled manner raise your body back up to the starting position."]},{"slug":"concentration-curls-with-dumbbell","title":"Concentration Curls with Dumbbell","idNum":"0220","type":"isolation","primary":["biceps"],"secondary":["forearm"],"equipment":["dumbbell"],"steps":["Sit on the end of a flat bench with your feet flat and your legs spread apart.","Grasp a dumbbell in your hand, palms facing up.","With your elbow pressed against your inner thigh, curl the dumbbell up towards your chest.","Slowly return to the starting position.","Repeat and switch arms.","Note: Keep all of your body still except the arm you are exercising."]},{"slug":"cross-body-crunch","title":"Cross Body Crunch","idNum":"0289","type":"compound","primary":["abdominals"],"secondary":[],"equipment":["body"],"steps":["Lie on your back and bring your knees up to a 60 degree angle, keep your feet flat on the floor.","Place your hands on either side of your head (over your ears).","Curl up raising your right elbow and your left knee so that they touch over your chest.","Return to the starting position and repeat with alternate arms and legs.","Note: Contract your abs as you twist during this exercise."]},{"slug":"cross-body-hammer-curl-with-dumbbell","title":"Cross Body Hammer Curl with Dumbbell","idNum":"0221","type":"isolation","primary":["biceps"],"secondary":["forearm"],"equipment":["dumbbell"],"steps":["While standing, grab a dumbbell in each arm with palms facing in.","Keeping your palms facing in (and not twisting your arms) curl the dumbbell up towards your opposite shoulder.","Bring the top of dumbbell up to and touching the shoulder.","Slowly with a controlled manner, lower the dumbbell back to the starting position."]},{"slug":"crossover-bands","title":"Crossover with Bands","idNum":"0050","type":"isolation","primary":["chest"],"secondary":["shoulders","biceps"],"equipment":["exercise band"],"steps":["This is an exercise for chest, biceps and shoulder strengthening.","Secure an exercise to a post (or secure pole) and hold it in each hand.","Step forward so the band has some tension, facing away from the post."," Your arms at mid chest height and out to the side, palms facing forward this is your starting position.","Bring your hands together in front of you.","Hold this for a moment and then in a controlled motion return to starting position."]},{"slug":"crunches","title":"Crunches","idNum":"0291","type":"isolation","primary":["abdominals"],"secondary":[],"equipment":["body"],"steps":["This is the most common abdominal exercise and possibly the most often improperly performed. Here is how to perform it correctly.","Lie on your back with your feet up on a bench and your knees bent at a 90 degree angle.","Place your hands across your chest or on either side of your head (over your ears).","Raise your head, shoulders and chest off the floor and towards your knees, crunching your abs.","Hold the position for a moment and then lower to the starting position.","Note: Keep your hips straight and your lower back against the floor during this exercise."]},{"slug":"crunches-with-legs-on-stability-ball","title":"Crunches with Legs on Stability Ball","idNum":"0290","type":"isolation","primary":["abdominals"],"secondary":[],"equipment":["stability ball"],"steps":["Lie on your back and place your feet up on a stability ball.","Place your hands across your chest, or on either side of your head.","Keeping the small of your back on the floor, raise your head, shoulders and chest up and off the floor.","Pause for a moment contracting your abs and then return to the starting position.","Note: Take your time and perform this exercise in a slow controlled manner."]},{"slug":"decline-barbell-bench-press","title":"Decline Barbell Bench Press","idNum":"0051","type":"isolation","primary":["chest"],"secondary":["triceps","shoulders"],"equipment":["decline bench","barbell"],"steps":["Lie on a decline bench with your head lower than your feet.","Grasp the bar at a grip 3-6 inches wider than your shoulders.","Raise the bar above your chest, keeping your elbows close in.","Slowly and with control lower the bar straight to your lower chest.","Raise the bar back up to starting position with the bar just above your chest.","Repeat."]},{"slug":"decline-chest-press","title":"Decline Chest Press","idNum":"0085","type":"isolation","primary":["chest"],"secondary":["shoulders","triceps"],"equipment":["chest machine"],"steps":["Adjust the seat of the machine so that the handles are near the lower portion of your chest.","Slowly press the handles forward until your hands are fully extended, do not lock your elbows.","Pause for a moment and then with a controlled movement lower your hands back to starting position."]},{"slug":"decline-close-grip-bench-to-skull-crusher","title":"Decline Close Grip Bench to Skull Crusher","idNum":"0168","type":"isolation","primary":["triceps"],"secondary":["chest"],"equipment":["barbell"],"steps":["Lay with your back on a flat bench.","Grip a barbell with a close grip 8-12 inches apart.","Keeping your arms close to your sides lower the bar so it touches your chest, approximately an inch below your nipples.","Slowly return to starting position, concentrating on your triceps.","At the top of the exercise bend your arms down towards your head.","Raise the bar back up over your chest and repeat."]},{"slug":"decline-crunch","title":"Decline Crunch","idNum":"0292","type":"isolation","primary":["abdominals"],"secondary":[],"equipment":["body"],"steps":["Lie on a decline bench face up.","Place your feet securely under the pads.","Place your hands either across your chest or on either side of your head (over your ears).","Lay fully back and then rise slowly crunching your abs.","Pause for a moment and then return to the starting position.","Note: Use the full range of movement in this exercise for the optimal results."]},{"slug":"decline-dumbbell-bench-press","title":"Decline Dumbbell Bench Press","idNum":"0052","type":"isolation","primary":["chest"],"secondary":["triceps","shoulders"],"equipment":["dumbbells","decline bench"],"steps":["Grasp the dumbbells your hands and lie on a decline bench with your head lower than your feet.","Raise the dumbbells above your chest, bringing your elbows close in, this is your starting position.","Slowly and with control lower the dumbbells to either side of your lower chest.","Raise the dumbbells back up to starting position."]},{"slug":"decline-dumbbell-flys","title":"Decline Dumbbell Fly's","idNum":"0053","type":"isolation","primary":["chest"],"secondary":["shoulders"],"equipment":["dumbbells","decline bench"],"steps":["Lie on a decline bench with your head lower than your body and your feet firmly on the ground.","With dumbbells together above your shoulders and your arms straight out above you as your starting position.","Keeping your arms straight and with a slight bend in your elbows lower the dumbbells down towards the floor in an arc, up until just above your shoulders.","Return to the starting position in a slow controlled manner.","Repeat."]},{"slug":"decline-ez-bar-triceps-extension-with-barbell","title":"Decline EZ Bar Triceps Extension with Barbell","idNum":"0170","type":"isolation","primary":["triceps"],"secondary":[],"equipment":["barbell"],"steps":["Lay face up on a decline bench and grasp an EZ Bar (Curved Barbell).","Extend your arms so they are perpendicular to your chest, and keeping your elbows in one place, lower the bar toward your head.","Slowly return to the starting position."]},{"slug":"decline-oblique-crunch","title":"Decline Oblique Crunch","idNum":"0293","type":"compound","primary":["abdominals"],"secondary":[],"equipment":["body"],"steps":["This version of a decline crunch isolates the oblique (side) muscles of the abs.","Lie on a decline bench face up.","Place your feet securely under the pads.","Place your hands either across your chest or on either side of your head (over your ears).","Raise your shoulders and chest up keeping your back straight and bring your left elbow to your right knee, slowly crunching your abs.","Pause for a moment and then return to the starting position.","Lay fully back and repeat with your right elbow to your left knee."]},{"slug":"decline-triceps-extension-with-dumbbell","title":"Decline Triceps Extension with Dumbbell","idNum":"0169","type":"isolation","primary":["triceps"],"secondary":[],"equipment":["dumbbell"],"steps":["Lay face up on a decline bench with a dumbbell in each hand.","Extend your arms so they are perpendicular to your chest, and keeping your elbows in one place, lower your hands so the dumbbells are lowered near your head.","Slowly return to the starting position."]},{"slug":"donkey-calf-raises","title":"Donkey Calf Raises","idNum":"0275","type":"isolation","primary":["calves"],"secondary":[],"equipment":["body"],"steps":["This is an old school gym exercise which requires the assistance of another person. This is an advanced exercise and not recommended for beginners.","Bend your waist and lean your arms against a weight rack or bench that is waist height.","Have a partner sit on top of your lower back.","Raise up on your toes leaning slightly forward.","Pause at the top and then lower your heels to the floor.","Note: Have a Personal Trainer or Instructor show you how to perform this exercise safely."]},{"slug":"drag-curl-with-barbell","title":"Drag Curl with Barbell","idNum":"0222","type":"isolation","primary":["biceps"],"secondary":["forearm"],"equipment":["barbell"],"steps":["This exercise is credited to the late Vince Gironda, the “Iron Guru”. It not only blasts the biceps and works the forearms as well.","Stand with your feet shoulder width apart, your knees slightly bent, and your abs drawn in.","Grasp the bar with palms down, shoulder width apart.","Extend your arms fully so they are against your thighs.","Slowly raise your arms, palms down, to touch your chest.","Note: Do not move your elbows or shoulders during this exercise."]},{"slug":"dumbbell-bent-arm-pullover","title":"Dumbbell Bent Arm Pullover","idNum":"0046","type":"isolation","primary":["chest"],"secondary":["shoulders","triceps","lats"],"equipment":["flat bench","dumbbell"],"steps":["Lie flat on a bench with your head hanging slightly over the end and your feet flat on the floor.","Hold a dumbbell with both hands, keep your elbows in throughout the exercise.","Starting with your arms fully extended over your chest, slowly lower the dumbbell in an arc over your head and towards the floor.","Pull the dumbbell back up to chest height in a slow controlled manner and return to starting position.","Repeat."]},{"slug":"dumbbell-dead-lifts","title":"Dumbbell Dead Lifts","idNum":"0107","type":"isolation","primary":["lower back"],"secondary":["calves","hamstring"],"equipment":["dumbbells"],"steps":["Grasp 2 dumbbells and stand with your feet shoulder width apart.","Keeping your back straight bend at the waist, allow some bend in your knees.","Grasp the dumbbells with an overhand grip in each hand.","Straighten your back as you hold the dumbbells at arm’s length.","Bend over again lowering the dumbbells to just above the floor.","Return to starting position.","Repeat."]},{"slug":"dumbbell-flys","title":"Dumbbell Flys","idNum":"0056","type":"isolation","primary":["chest"],"secondary":["shoulders","triceps"],"equipment":["flat bench","dumbbells"],"steps":["Lie on a flat bench with a dumbbell in each hand and your feet firmly on the ground.","Lift the dumbbells over your chest extending your arms fully with a slight bend in your elbows, this is your starting position.","Keeping a slight bend in your elbows, lower the dumbbells to the floor in an arc like motion.","Slowly return the dumbbells over your chest to the starting position in a controlled motion.","Repeat."]},{"slug":"dumbbell-incline-bench-press","title":"Dumbbell Incline Bench Press","idNum":"0061","type":"isolation","primary":["chest"],"secondary":["triceps","shoulders"],"equipment":["dumbbells","incline bench"],"steps":["Lie on an incline bench which has been set to an incline of 45 degrees.","Start with the dumbbells at shoulder height, your arms wide and elbows pointing down to the floor.","Grasp the dumbbells with a grip so your palms face each other.","Raise your arms up over your chest bringing the dumbbells closer together as they meet over your chest, as if you were clapping.","Slowly return the dumbbells to starting position."]},{"slug":"dumbbell-lunges","title":"Dumbbell Lunges","idNum":"0115","type":"isolation","primary":["hamstring"],"secondary":["gluts","quadriceps","calves"],"equipment":["dumbbells"],"steps":["Grasp a dumbbell in each hand.","Stand with your feet about 8 inches apart, toes facing forward.","Take a step forward (2-3 feet) keeping your abs drawn in and your upper body straight.","Slowly lower one knee down as if kneeling while keeping your other knee bent at a 90 degree angle, do not let your knee touch the ground.","Lower your body so that the rear knee is just above the floor and hold for a moment before returning to the starting position.","Repeat on opposite side."]},{"slug":"dumbbell-upright-rows","title":"Dumbbell Upright Rows","idNum":"0016","type":"isolation","primary":["shoulders"],"secondary":["biceps","upper back"],"equipment":["dumbbells"],"steps":["Grasp a dumbbell in each hand with an overhand grip (palms facing downwards) and hold them in front of your thighs.","Stand with your feet shoulder width apart, your abs drawn in and your back straight.","Starting with the dumbbells at your thighs, slowly raise them up towards your shoulders by bending your elbows.","Pause at the top and rotate your shoulder blades together.","Lower the dumbbells in a controlled motion to your thighs.","Repeat"]},{"slug":"exercise-ball-pull-in","title":"Exercise Ball Pull In","idNum":"0296","type":"compound","primary":["abdominals"],"secondary":[],"equipment":["body"],"steps":["Lay down as if you were performing a pushup.","Place your feet and shins over an exercise or stability ball.","Keeping your back straight and supporting your weight on your hands, pull your knees towards your chest, so the ball rolls forward under your ankles.","Crunch your abs and then roll the ball back to starting position straighten your legs.","Note: Keep your back straight as you perform this exercise."]},{"slug":"ez-bar-curl-with-barbell","title":"EZ Bar Curl with Barbell","idNum":"0226","type":"isolation","primary":["biceps"],"secondary":["forearm"],"equipment":["barbell"],"steps":["Stand with your feet shoulder width apart and your knees slightly bent.","Grasp the barbell with palms up.","Lower the bar so it is against your thighs.","Keeping your elbows still, raise the bar up to your chest so that your forearms touch your biceps.","Note: Lean up against a wall or post to keep yourself from swaying."]},{"slug":"flat-bench-cable-flys","title":"Flat Bench Cable Flys","idNum":"0057","type":"isolation","primary":["chest"],"secondary":["shoulders"],"equipment":["flat bench","cable machine"],"steps":["<h3> Steps</h3>","Lie on flat bench between two cable towers and your feet firmly on the ground.","Grasp a pulley in each hand with your palms facing up.","With a slight bend in your elbows, squeeze your chest and pull the cables together meeting in the middle of your chest.","Hold for a moment and then slowly lower your hands back to starting position at bench height.","<h3>Tip</h3>","Ensure your back and hips stay in contact with the bench at all times during this exercise."]},{"slug":"flat-bench-leg-raises","title":"Flat Bench Leg Raises","idNum":"0021","type":"isolation","primary":["lower abdominals"],"secondary":[],"equipment":["body"],"steps":["Lie on a flat bench with your hands under your hips supporting your back.","Your legs should be unsupported by the bench from below your knees.","With your feet together and your toes flexed upwards, raise your straight legs up a few cm off the bench; both of your legs should have no contact with the bench. This is your starting position.","Keep your legs straight with a slight bend in the knees and raise your legs to just before 90 degrees with your hips.","Pause at the top and lower your legs in slow controlled manner back to the starting position.","Repeat."]},{"slug":"flexor-incline-curls-with-dumbbell","title":"Flexor Incline Curls with Dumbbell","idNum":"0228","type":"isolation","primary":["biceps"],"secondary":[],"equipment":["dumbbell"],"steps":["Sit on an incline bench with your feet firmly on the floor in front of you.","Grasp a dumbbell with your palms facing up.","Bring your arms down to your sides and while keeping your wrists as straight as possible, raise your wrists to your shoulders.","Concentrate on squeezing your biceps as you contract (raise) your arms."]},{"slug":"flutter-kicks","title":"Flutter Kicks","idNum":"0116","type":"isolation","primary":["hamstrings"],"secondary":["quadriceps"],"equipment":["flat bench"],"steps":["Lie face down on a bench with your hips on the edge, hold onto the bench with your hands.","Allow your legs and toes hang down.","Draw your abs in, squeeze your gluts and hamstrings.","Kick each back and up while keeping your hips on the bench.","Alternate kicking each leg."]},{"slug":"forward-lunge-with-biceps-curl-using-dumbbell","title":"Forward Lunge with Bicep Curl using Dumbbell","idNum":"0265","type":"compound, isolation","primary":["biceps"],"secondary":["calves","hip abductors","forearm","hamstrings","glutes"],"equipment":["dumbbell"],"steps":["Grasp a dumbbell in each hand with your palms facing up.","Stand with your feet together, your back straight and your abs drawn in.","Allow your arms to extend down fully to the sides of your body.","While keeping your body straight, take a step forward then bend your waist and your knee into a lunge.","Be careful not to let your back knee drop to the floor.","As you go into the lunge, curl your arms up towards your shoulders, contracting your biceps.","Return to starting position and switch legs.","Note: Have a Personal Trainer or Instructor show you how to properly perform this exercise."]},{"slug":"front-cable-raises","title":"Front Cable Raises","idNum":"0008","type":"isolation","primary":["shoulders"],"secondary":["chest","forearm"],"equipment":["cable machine"],"steps":["Place the pulley on the setting just above the floor.","Stand with your feet shoulder width apart, your abs drawn in and your knees slightly bent.","Starting at waist height, take the pulley in your left hand, palm facing the floor with otherwise known as an overhand grip, and raise your straight arm up towards your left shoulder.","At shoulder height pause for a moment.","With a controlled movement resist the weight and slowly lower your arm back to starting position at your waist.","Repeat the exercise with your right arm."]},{"slug":"front-dumbbell-raise","title":"Front Dumbbell Raise","idNum":"0033","type":"isolation","primary":["shoulders"],"secondary":[],"equipment":["dumbbells"],"steps":["Stand with a dumbbell in each hand with an overhand grip, your feet shoulder width apart and your abs drawn in.","Keeping each arm straight raise your left arm to just above shoulder height.","Pause for a moment then in a controlled motion lower the weight to starting position and repeat with your right arm.","<h3></h3>"]},{"slug":"front-squat-to-bench-with-barbells","title":"Front Squat to Bench with Barbells","idNum":"0139","type":"compound","primary":["quadriceps"],"secondary":["hamstrings","calves"],"equipment":["barbell"],"steps":["The Front Squat works the same muscles as the rear squat without placing the weight of the bar on your shoulders. This exercise can be a good substitute for people with back and neck injuries. By using a bench you remind yourself how far to squat down","Steps","Place a bench behind you.","Place the barbell on your upper chest, resting it across your front deltoids and holding it with your arms crossed securely.","Keep your head and back straight, abs drawn in and your toes pointing slightly outward.","Slowly “squat” down so your upper thighs are parallel to the floor.","Slowly return to the starting position.","Note: Practice the squat without any weight to allow yourself to become comfortable with the movements. Do not sit on the bench during the exercise."]},{"slug":"front-squat-with-barbell","title":"Front Squat with Barbell","idNum":"0138","type":"compound","primary":["quadriceps"],"secondary":["hamstrings","calves"],"equipment":["barbell"],"steps":["The Front Squat works the same muscles as the rear squat without placing the weight of the bar on your shoulders. This exercise can be a good substitute for people with back and neck injuries.","Place the barbell on your upper chest, resting it across your front deltoids and holding it with your arms crossed securely.","Keep your head and back straight, abs drawn in and toes pointing slightly outward.","Slowly “squat” down so your upper thighs are parallel to the floor.","Slowly return to the starting position.","Note: Practice the squat without any weight to allow yourself to become comfortable with the movements."]},{"slug":"hack-squat-machine","title":"Hack Squat Machine","idNum":"0123","type":"compound","primary":["quadriceps"],"secondary":["hamstrings","calves"],"equipment":["machine"],"steps":["This exercise is a variation of the Squat which uses a machine.  This exercise may be preferred by beginners.","Lie face up on a Hack Squat machine with your shoulders against the pad.","Place your feet facing forward at slightly less than shoulder width apart with your toes point slightly outward.","Release the dock levers and place your hands on the hand grips.","Drawing your abs in, extend your body standing upright.","Lower your body to a squatting position so you knees are bent as if you were sitting down.","Return to the starting position."]},{"slug":"hack-squat-with-barbell","title":"Hack Squat with barbell","idNum":"0125","type":"compound","primary":["quadriceps"],"secondary":["hamstrings"],"equipment":["barbell"],"steps":["This is another variation of the basic Squat that focuses primarily on the quadriceps or thigh muscles.","Place the barbell on the floor just behind your legs and stand with your feet shoulder width apart with your toes pointing forward.","With your feet firmly placed on the floor, reach down and grasp the barbell from behind with an overhand grip.","Lift the barbell by extending your hips and knees, taking care not to lock your knees.","Lower yourself (squat) down until your thighs are parallel to the floor.","Slowly raise yourself up to starting position."]},{"slug":"hammer-curls-with-rope-and-cable","title":"Hammer Curls with Rope and Cable","idNum":"0216","type":"isolation","primary":["biceps"],"secondary":[],"equipment":["cable"],"steps":["Using the rope with the cable machine allows you isolate the biceps with this version of the Hammer Curl. This is a good exercise for beginners.","Attach a rope to a cable pulley to the bottom of the weight stack. Stand with your feet shoulder width apart, your knees slightly bent and your abs drawn in. Grasp the rope with a close underhand grip (palms facing up). Lower your arms fully to above your thighs and bending only your elbows, raise the rope to your upper chest. Pause for a moment and then return to the starting position.","Note: Keep your elbows at your side throughout this exercise. Do not swing your hips or back during this exercise."]},{"slug":"hammer-grip-incline-bench-press","title":"Hammer Grip Incline Bench Press","idNum":"0059","type":"isolation","primary":["chest"],"secondary":["shoulders","triceps"],"equipment":["dumbbells","incline bench"],"steps":["Grasp a dumbbell in each hand and lay on an incline bench set at a 45 degree angle.","Keep your feet flat on the floor and your back against the bench at all times.","Using a hammer grip (with your palms facing each other), lift the weights to shoulder height on either side of your chest.","Extend your arms fully and press the dumbbells up.","Slowly return the dumbbells to the starting position at the sides of your chest."]},{"slug":"high-cable-curls","title":"High Cable Curls","idNum":"0229","type":"isolation","primary":["biceps"],"secondary":["triceps"],"equipment":["cable"],"steps":["Place a flat bench next to a cable weigh stack.","Attach a short bar to the high pulley.","Lay on your back with your head towards the stack.","Grip the bar with palms facing you)and extend your arms fully on a slight angle over your head.","Pull the bar down towards you, curling your arms as much as possible.","Slowly return to the starting position."]},{"slug":"hip-adduction","title":"Hip Adduction","idNum":"0135","type":"isolation","primary":["quadriceps"],"secondary":["hip abductors"],"equipment":["cable"],"steps":["Stand alongside a cable pulley stack and attach a cuff to the pulley and your ankle.","Step away from the stack, holding onto the stack for support.","Standing firm on the foot not attached to the cable and slowly abduct, or pull, your cuffed ankle in front of your stabilizing leg.","Repeat and switch ankles."]},{"slug":"hyperextensions","title":"Hyperextensions","idNum":"0103","type":"isolation","primary":["lower back"],"secondary":["hamstrings","core"],"equipment":["hyperextension bench"],"steps":["Adjust the hyperextension bench so that your ankles are tucked under the footpads and your thighs are flat across the top pad.","With your arms folded across your chest and your back straight, slowly bend at the waist towards the floor, keeping your back flat.","Slowly return to the starting position.","Repeat."]},{"slug":"incline-bench-press","title":"Incline Bench Press","idNum":"0043","type":"isolation","primary":["chest"],"secondary":["triceps"],"equipment":["incline bench","barbell"],"steps":["Lie flat on an incline bench set at a 45 degree angle, with your feet shoulder width apart.","Grasp the bar a little wider than shoulder width apart.","Raise the barbell above your body and move it over the middle of your chest, this is your starting position.","Lower the bar down so it just touches your chest.","Raise the bar straight up till your arms are fully extended and your elbows are locked.","Return to starting position."]},{"slug":"incline-bench-press-with-bands","title":"Incline Bench Press with Bands","idNum":"0044","type":"isolation","primary":["chest"],"secondary":["biceps"],"equipment":["exercise band","incline bench"],"steps":["Securely fasten the band under the leg of a flat bench, near your head.","Lie flat on the bench with your feet flat on the floor in order to stabilise your movements.","Grasp one end of the band in each hand and starting with your hands at chest level.","Press upwards so your arms are fully extended.","With a slow controlled motion return to starting position."]},{"slug":"incline-cable-flys","title":"Incline Cable Fly's","idNum":"0060","type":"isolation","primary":["chest"],"secondary":["biceps","triceps","forearm"],"equipment":["incline bench","cable machine"],"steps":["Place an incline bench set at a 45 degree angle between two cable towers.","Grasp a pulley in each hand with your palms facing up.","With a slight bend in your elbows, squeeze your chest and pull the cables in an arc so they meet together in the middle of your chest.","Hold for a moment and then slowly lower your hands back to starting position at along the same arc."]},{"slug":"incline-dumbbell-flys","title":"Incline Dumbbell Fly's","idNum":"0062","type":"isolation","primary":["chest"],"secondary":["shoulders"],"equipment":["incline bench","dumbbells"],"steps":["Lie on an incline bench set a 45 degree angle with a dumbbell in each hand and your feet firmly on the ground.","Lift the dumbbells over your chest extending your arms fully and your palms facing each other.","Keeping a slight bend in your elbows, lower the dumbbells towards the floor in and arc like motion.","Slowly return to starting position."]},{"slug":"incline-dumbbell-press","title":"Incline Dumbbell Press","idNum":"0080","type":"isolation","primary":["chest"],"secondary":["triceps","shoulders"],"equipment":["dumbbells","incline bench"],"steps":["Set and incline bench at a 45 degree angle.","Start with the dumbbells at shoulder height, your arms wide and elbows pointing down to the floor.","Raise your arms up over your chest bringing the dumbbells closer together as they meet over your chest.","Slowly return the dumbbells to starting position.","Repeat."]},{"slug":"incline-flys-twist","title":"Incline Fly's with a Twist","idNum":"0063","type":"isolation","primary":["chest"],"secondary":["shoulders"],"equipment":["incline bench","dumbbells"],"steps":["Lie on an incline bench set at a 45 degree angle with a dumbbell in each hand and your feet flat on the ground.","Start with the dumbbells out to the sides of your chest, parallel to the floor as you would a regular Fly.","Raise the dumbbells over your chest in and arc, at the top turn your pinky finger in so they are facing each other.","Slowly return to starting position.","Repeat."]},{"slug":"incline-inner-biceps-curl-with-dumbbell-2","title":"Incline Inner Biceps Curl with Dumbbell","idNum":"0231","type":"isolation","primary":["biceps"],"secondary":[],"equipment":["dumbbell"],"steps":["This exercise uses an incline bench and twist to more to change your body’s position as you perform Biceps Curls. The movement is very similar to a Preacher Curl."," Adjust an incline bench to a 45 degree angle.","Grasp dumbbells in each hand with and sit down with your back against the bench, with your feet resting on the floor for support.","Allow your arms to hang down at your sides, your palms facing your body.","Keeping your elbow straight, raise the dumbbells up towards your head, contracting your biceps.","In a controlled manner lower the weight and repeat.","Note: Practice steady movements in this exercise, be careful not to let your arms sway."]},{"slug":"incline-pushdown-with-cable","title":"Incline Pushdown with Cable","idNum":"0163","type":"isolation","primary":["triceps"],"secondary":[],"equipment":["cable"],"steps":["This exercise uses cables to isolate and work the triceps (muscles on the back of the arms).","Place an incline bench facing away from a cable pulley.","Attach a short straight bar to the pulley and adjust the height so that your arms can extend fully.","Lie face up on the bench and grasp the bar with a narrow overhand grip.","Keeping your arms straight, slowly push the bar down towards your feet.","Pause at the bottom and then return to starting position.","Note: Keep your elbows steady throughout this exercise."]},{"slug":"incline-shoulder-press-dumbbell","title":"Incline Shoulder Press Dumbbell","idNum":"0031","type":"isolation","primary":["shoulders"],"secondary":[],"equipment":["dumbbell"],"steps":["Lie down on an incline bench with your feet flat on the floor and grasp the dumbbells.","With your elbows bent raise your arms up until in line with your shoulders this is your starting position.","With your abs drawn in, raise the dumbbells as high as you are able above your shoulders.","Lower the dumbbells in a slow controlled manner to starting position."]},{"slug":"incline-triceps-extension-with-barbell","title":"Incline Triceps Extension with Barbell","idNum":"0174","type":"isolation","primary":["triceps"],"secondary":[],"equipment":["barbell"],"steps":["Grasp a barbell with a close grip (4-6 inches apart).","Lie on an incline bench and hold the bar over your head.","Lower your arms in a slight arc so your forearms are touching your biceps.","Slowly return back to the starting position with the bar over your head."]},{"slug":"incline-triceps-extension-with-cable","title":"Incline Triceps Extension with Cable","idNum":"0164","type":"isolation","primary":["triceps"],"secondary":[],"equipment":["cable"],"steps":["This exercise uses cables to isolate and work the triceps (muscles on the back of the arms).","Place an incline bench facing away from a cable pulley.","Attach a short straight bar to the pulley and adjust the height so that your arms can extend fully.","Lie face up on the bench and grasp the bar with a narrow overhand grip.","Starting with your elbows bent overhead, slowly lower the bar towards your feet.","Pause at the bottom and then return to starting position."]},{"slug":"incline-triceps-extensions-with-dumbbell","title":"Incline Triceps Extensions with Dumbbell","idNum":"0209","type":"isolation","primary":["triceps"],"secondary":["shoulders"],"equipment":["dumbbell"],"steps":["Grasp a dumbbell in each hand and lie against an incline bench, face up with your feet firmly planted on the floor.","Extend your arms over your shoulders with your palms facing each other.","Slowly lower the dumbbells behind your head by bending your elbows.","With a controlled motion raise your arms back up to the starting position."]},{"slug":"internal-cable-rotation","title":"Internal Cable Rotation","idNum":"0034","type":"compound","primary":["shoulders"],"secondary":["biceps"],"equipment":["cable machine"],"steps":["Sit on the floor with your body close to low cable pulley.","Grasp the pulley with your left arm and position your elbow bent at 90 degree angle.","Pull the cable towards your body and internally rotate your shoulder until your forearm is across your abs.","Return to starting position.","Repeat with right arm."]},{"slug":"iron-cross-with-dumbbells","title":"Iron Cross with Dumbbells","idNum":"0140","type":"compound","primary":["quadriceps"],"secondary":["trapezius","glutes","shoulders","lower back","hamstrings"],"equipment":["dumbbells"],"steps":["With a dumbbell in each hand, stand in a low squat stance, your feet shoulder width arms held out in front of you with your palms facing in.","Standing upright, move your arms out and away from your body forming a “T” or “cross”.","Note: Do this exercise with light weights until you are comfortable with the movements."]},{"slug":"jefferson-squats-with-barbell","title":"Jefferson Squats with Barbell","idNum":"0141","type":"compound","primary":["hamstrings"],"secondary":[],"equipment":["barbell"],"steps":["This is a rarely used exercise which is without question one of the best exercises for building and shaping the inner thighs.","Place a barbell between your legs so it is perpendicular to your feet.","Grasp the barbell with one hand in front of you and one hand behind you with an overhand grip.","Squatting down so your thighs are parallel to the floor slowly lift the weight up between your legs as you stand.","Slowly return to a starting position just above the floor."]},{"slug":"jm-press","title":"JM Press","idNum":"0175","type":"compound","primary":["triceps"],"secondary":["shoulders"],"equipment":["barbell"],"steps":["This exercise is named after the inventor, J.M. Blakley. This is an advanced exercise used by bodybuilders and power lifters to build explosive power in the triceps muscle (back of the arms).","Lay on a flat bench with your head just at the end of the bench.","Grasp the bar with a medium overhand grip keeping your elbows close to your side, over your sternum (mid chest).","Lower the bar towards your sternum at a regular pace, then pause for a moment.","With a controlled but rapid pace, push the bar back to starting position.","Note: The bar should move in straight line, up and down."]},{"slug":"knee-circles","title":"Knee Circles","idNum":"0277","type":"compound","primary":["calves"],"secondary":["hamstrings"],"equipment":["body"],"steps":["Stand with your feet a little closer than shoulder width apart.","Keeping your arms across your chest or on your hips, move your knees in a circular motion, paying attention to keeping your feet flat on the floor and the movement in your ankles.","Note: Do not perform this exercise is you have rolled or unstable ankles."]},{"slug":"kneeling-triceps-extension-with-cable","title":"Kneeling Triceps Concentration Extension with Cable","idNum":"0176","type":"isolation","primary":["triceps"],"secondary":[],"equipment":["cable"],"steps":["Attach a stirrup handle to a cable pulley and adjust the pulley up high.","Kneeling on your left knee, with the left side of your body turned towards the machine, keep your right leg bent and the upper portion of your thigh parallel to the floor.","With your right elbow and upper arm pressed against your inner thigh just above your knee, pull the cable down towards the floor in a slight arcing motion.","Slowly to return to starting position.","Repeat and switch arms.","Note: Keep all of your body still except the arm you are exercising."]},{"slug":"kneeling-triceps-extension-with-cable-2","title":"Kneeling Triceps Extension with Cable","idNum":"0177","type":"isolation","primary":["triceps"],"secondary":[],"equipment":["cable"],"steps":["Place a bench sideways in front of a high pulley machine.","Grasp a straight bar with an over head grip.","Kneel on the floor in front of the bench with your back straight and your head down.","With your elbows and forearms above your head, push the bar down in an arc so that your forearms are touching the bench.","Note: Keep your abs drawn in and your back straight as you perform this exercise."]},{"slug":"lateral-dumbbell-raises","title":"Lateral Dumbbell Raises","idNum":"0018","type":"isolation","primary":["lateral deltoid"],"secondary":["forearm","shoulders"],"equipment":["dumbbells"],"steps":["Grasp a dumbbell in each hand, palms facing inward towards your body and the dumbbells at your sides.","Standing with your feet shoulder with apart, draw your abs in and bend your knees slightly.","While keeping your torso still, raise the your arms up to the sides keeping your arms straight with a slight bend in the elbows.","Raise your arms up until in line with your shoulders, your palms should face the floor.","Hold the position for a moment then in a controlled movement lower your arms to the starting position.","Repeat"]},{"slug":"lateral-lunge-with-biceps-curl-with-dumbbell","title":"Lateral Lunge with Bicep Curl with Dumbbell","idNum":"0264","type":"compound, isolation","primary":["quadriceps","biceps"],"secondary":["forearm","hamstrings","glutes","calves","hip abductors"],"equipment":["dumbbell"],"steps":["Grasp a dumbbell in each hand with your palms facing up.","Stand with your feet together, your back straight and your abs drawn in.","Allow your arms to extend down fully in front of your thighs.","While keeping your body straight, take a step sideways and then bend your waist and your knee into a lunge.","As you go into the lunge, curl your arms up towards your shoulders contracting your biceps.","Return to starting position and switch legs.","Note: Have a Personal Trainer or Instructor show you how to properly perform this exercise."]},{"slug":"leg-extensions","title":"Leg Extensions","idNum":"0142","type":"isolation","primary":["quadriceps"],"secondary":[],"equipment":["machine"],"steps":["Adjust the seat so that your knees have full range of motion and that the footpad fits over your legs, just above your ankles.","Grasp the handles with your hands for support, keeping your hip and back against the bench.","Slowly extend your legs until your knees are straight, but do not lock your knees.","Hold for a moment and then with controlled movements return to the starting position.","Note: Use controlled movements for this exercise, do not swing the weight up."]},{"slug":"leg-press","title":"Leg Press","idNum":"0127","type":"compound","primary":["quadriceps"],"secondary":["calves","hamstrings"],"equipment":["machine"],"steps":["Along with the Squat, this exercise is crucial for building and strengthening the legs.","Adjust the seat of the machine so that your feet comfortably reach the crosspiece with a slight bend in your knees.","To begin, press your feet forward at a shoulder width stance and release the safety locks.","Slowly lower the weight towards your body, keeping your abs drawn in and your knees moving in the same direction as your feet to a 90 degree angle.","Do not lock your knees or bounce the weight."]},{"slug":"low-triceps-extension-with-cable","title":"Low Triceps Extension with Cable","idNum":"0178","type":"isolation","primary":["triceps"],"secondary":[],"equipment":["cable"],"steps":["Attach a rope to the cable pulley at of a seated row station.","Lie on your back on the bench with your head facing the weight stack.","Grasp the rope with your palms facing each other and raise your arms over your chest, with your forearms parallel to the floor at a 90 degree angle.","Slowly extend your arms upward squeezing your triceps.","Return to starting position."]},{"slug":"lying-bicep-cable-curl","title":"Lying Bicep Cable Curl","idNum":"0232","type":"isolation","primary":["biceps"],"secondary":["forearm"],"equipment":["cable"],"steps":["Attach a short bar to a cable pulley set on the lowest setting.","Lie down on a mat or the floor with your feet touching the weight stack.","Grasp the bar with and palms facing up.","With your arms fully extended and your elbows at your sides, pull the bar in an arc to your chest.","Pause for a moment contracting your biceps, and then return to the starting position."]},{"slug":"lying-close-grip-biceps-curls-with-cable","title":"Lying Close Grip Biceps Curls with Cable","idNum":"0233","type":"isolation","primary":["biceps"],"secondary":[],"equipment":["cable"],"steps":["Place a flat bench under a cable weight stack and attach a flat bar to the pulley.","Lie down with your head towards the stack and your feet firmly on the floor.","Grasp the bar with your palms down, about 8 inches apart, and extend your arms straight up.","Curl the bar down in an arc touching your chin.","Slowly return to the starting position."]},{"slug":"lying-close-grip-triceps-press-to-chin-with-barbell","title":"Lying Close Grip Triceps Press to Chin with Barbell","idNum":"0180","type":"isolation","primary":["triceps"],"secondary":[],"equipment":["barbell"],"steps":["Lie on a flat bench on your back, with your head at one end.","Grasp a bar with a close grip, approximately 6 inches apart.","Raise the bar straight up over your shoulders, keeping your elbows close in.","Slowly lower the bar in an arc towards your chin.","Return the bar to the starting position."]},{"slug":"lying-close-grip-triceps-extension-behind-the-head-with-barbell","title":"Lying Close-Grip Triceps Extension Behind the Head with Barbell","idNum":"0179","type":"isolation","primary":["triceps"],"secondary":[],"equipment":["barbell"],"steps":["You can use a barbell or EZ (curl) bar to further concentrate the benefit to your triceps.","Lie flat on a bench on your back.","Grasp the bar with a grip approximately 8 inches apart and lower the bar behind your head.","Keeping the bar parallel with the floor, bend your arms down in an arc so the bar moves in a direction under your head.","Slowly return to starting position."]},{"slug":"lying-high-bench-biceps-curl-with-barbell","title":"Lying High Bench Biceps Curl with Barbell","idNum":"0234","type":"isolation","primary":["biceps"],"secondary":[],"equipment":["barbell"],"steps":["With this exercise your lay face down to isolate your biceps.","Lay face down on a high bench with your head at one end and your toes pressed against the floor to support you.","Grasp a barbell with palms facing up, about 12 inches apart.","Extending your arms to the floor, curl your arms back towards your head in a slight arc, so your biceps touch your forearm.","Slowly return to the starting position."]},{"slug":"lying-incline-curl-with-barbell","title":"Lying Incline Curl with Barbell","idNum":"0215","type":"isolation","primary":["biceps"],"secondary":[],"equipment":["barbell"],"steps":["This exercise uses an incline bench to change your body’s position as you perform Biceps Curls. The movement is very similar to a Preacher Curl.","Adjust an incline bench to a 45 degree angle.","Grasp a barbell with a shoulder width grip and lean face down against the bench, with your feet resting on the floor for support.","Allow your arms to hang down at your sides.","Keeping your elbows straight, raise the bar up towards your head, contracting your biceps.","In a controlled manner lower the weight and repeat.","Note: Practice steady movements in this exercise, be careful not to let your arms sway."]},{"slug":"lying-leg-curl-machine","title":"Lying Leg Curl Machine","idNum":"0117","type":"isolation","primary":["hamstring"],"secondary":[],"equipment":["machine"],"steps":["Lie face down on a leg curl machine and place your heels under the roller pad.","Grasp the grips with your hands for support and slowly curl your ankles up towards your back.","Hold for a moment and then return to starting position.","Repeat."]},{"slug":"lying-one-arm-rear-lateral-raise","title":"Lying One Arm Rear Lateral Raise","idNum":"0037","type":"isolation","primary":["shoulders"],"secondary":[],"equipment":["dumbbell","flat bench"],"steps":["Lay face down on a flat bench high enough for your arms to hang down to the floor.","Place a dumbbell at your side.","Your other hand not grasping the dumbbell can be on the floor stabilising your movements.","Grasp the dumbbell in your hand and raise your upper arm to shoulder height.","Keep your arm straight and perpendicular to your chest with a slight bend in the elbow.","In a slow controlled manner lower your arm to starting position."]},{"slug":"lying-rear-lateral-raise","title":"Lying Rear Lateral Raise","idNum":"0023","type":"isolation","primary":["shoulders"],"secondary":[],"equipment":["flat bench","dumbbells"],"steps":["Place the dumbbells at he head of the bench.","Lie facedown on a raised bench; raised enough for your arms to move freely beneath the bench.","Place your toes on the floor in order to stabilise yourself.","Grasp the dumbbells and with a 30 degree bend in your elbows, this is the starting position.","Raise your arms to shoulder height, maintaining a controlled motion.","Return to starting position and repeat."]},{"slug":"lying-squat","title":"Lying Squat","idNum":"0144","type":"compound","primary":["quadriceps"],"secondary":["calves","hamstrings"],"equipment":["machine"],"steps":["Adjust the shoulder rack of the machine so that your feet comfortably reach the crosspiece with a slight bend in your knees.","To begin, press your feet forward and release the safety locks.","Slowly lower the weight towards your body, keeping your abs drawn in and your knees moving in the same direction as your feet to a 90 degree angle.","Do not lock your knees or bounce the weight."]},{"slug":"lying-supine-biceps-curl-with-dumbbell","title":"Lying Supine Biceps Curl with Dumbbell","idNum":"0235","type":"isolation","primary":["biceps"],"secondary":[],"equipment":["dumbbell"],"steps":["This is another biceps exercise where you lay down to isolate the muscles you are working. This is an advanced exercise.","Lie on a flat bench with your head at one end and your feet planted firmly on the floor.","With a dumbbell in each hand, palms facing in, bring your arms down to your sides, hanging off the bench.","Slowly raise your arms up until they are level with your chest.","Curl the dumbbells by twisting your palms, so that your forearms touch your biceps.","Slowly lower your arms to the starting position.","Note: Practice the motions of this exercise with light weights to become familiar with the movements."]},{"slug":"lying-triceps-extension-with-cable","title":"Lying Tricep Extension with Cable","idNum":"0165","type":"isolation","primary":["triceps"],"secondary":[],"equipment":["cable"],"steps":["This exercise uses cables to isolate and work the triceps (muscles on the back of the arms).","Place a flat bench with the end towards a weight stack.","Attach a short straight bar to the pulley and lower the pulley to the bottom of the stack.","Lie face up on the bench and grasp the bar with a narrow overhand grip.","Starting with your arms extended lower the bar towards the bar towards the stack by bending your elbows.","Slowly extend your arms upright and return to the starting position.","Note: Keep your elbows level throughout the exercises."]},{"slug":"lying-triceps-extension-across-face-with-dumbbell","title":"Lying Triceps Extension Across Face with Dumbbell","idNum":"0182","type":"isolation","primary":["triceps"],"secondary":[],"equipment":["dumbbell"],"steps":["This is an advanced exercise and should be avoided by beginners.","Lay on a flat bench with your head at one end and your feet planted firmly on the floor.","Grasp a dumbbell in each hand with palms facing up.","Raise dumbbells over your body. Your arms will be pointed towards the ceiling.","While keeping your upper arms and elbows still, lower the dumbbell slowly over your face bending only your elbow.","Slowly raise the dumbbell back to the starting position and repeat with your other arm.","Note: Do not perform this exercise if your arms are fatigued, as you are lifting the weight over your face."]},{"slug":"lying-triceps-extension-with-dumbbells","title":"Lying Triceps Extension with Dumbbells","idNum":"0181","type":"isolation","primary":["triceps"],"secondary":[],"equipment":["dumbbell"],"steps":["Lay on a flat bench with your head at one end and your feet planted firmly on the floor.","Grasp a dumbbell with both hands with palms facing up.","Raise dumbbell over your body. Your arms will be pointed towards the ceiling.","While keeping your upper arms and elbows still, lower the dumbbell in an arc behind your head.","Slowly raise the dumbbell back to the starting position."]},{"slug":"lying-triceps-press-with-barbell","title":"Lying Triceps Press with Barbell","idNum":"0183","type":"isolation","primary":["triceps"],"secondary":["chest"],"equipment":["barbell"],"steps":["Lie on a flat bench with your head at one end.","Grasp an EZ or Curl bar with an overhand grip.","Raise the bar straight up over your shoulders, taking care to keep your elbows in close.","Slowly lower the bar in an arc over your head.","Return the bar to the starting position.","Note: Keep your arms straight throughout this exercise moving only your elbows."]},{"slug":"lying-two-arm-triceps-extension-with-dumbbell","title":"Lying Two Arm Triceps Extension with Dumbbell","idNum":"0184","type":"isolation","primary":["triceps"],"secondary":[],"equipment":["dumbbell"],"steps":["Lie flat on a bench, on your back, with your head at one end.","Grasp a dumbbell in each hand and raise them at arms length over your shoulders.","Lower the dumbbells in an arc bending your elbows until your forearms are touching your biceps.","Slowly return to the starting position."]},{"slug":"machine-bench-press","title":"Machine Bench Press","idNum":"0066","type":"isolation","primary":["chest"],"secondary":["triceps","shoulders"],"equipment":["bench press machine"],"steps":["Adjust the machine so that you are sitting with the bars at chest height.","Place your hands on the bars and place your feet on the foot rest.","Press out, extending your arms as far as possible in a steady motion.","Pause for a moment and then return slowly to starting position."]},{"slug":"medicine-ball-biceps-curl-on-stability-ball","title":"Medicine Ball Biceps Curl on Stability Ball","idNum":"0267","type":"isolation","primary":["biceps"],"secondary":["core","forearm"],"equipment":["medicine ball"],"steps":["Sit on a Stability Ball with your feet firmly on the floor in front of you.","Sit with your back straight, your shoulders back and your abs drawn in.","Hold a Medicine Ball in one hand and curl it up bringing your forearm up to your bicep.","Return to starting position and switch arms.","Note: Grasp the Medicine Ball with your fingers spread wide to balance the ball."]},{"slug":"narrow-parallel-grip-chin-ups","title":"Narrow Parallel Grip Chin-ups","idNum":"0090","type":"isolation","primary":["shoulders","lats"],"secondary":["back","core"],"equipment":["bar","body"],"steps":["Grasp the bar with an supinated (overhand) grip so that your palms are facing.","Let your body hang from the bar with your arms straight.","Slowly pull yourself up so that your chin is higher than the bar.","With a controlled movement lower yourself to the starting position.","Repeat"]},{"slug":"narrow-stance-hack-squats","title":"Narrow Stance Hack Squats","idNum":"0145","type":"compound","primary":["quadriceps"],"secondary":["hamstrings","calves"],"equipment":["machine"],"steps":["Like the Hack Squat, this exercise works the muscles of the leg. The narrow stance targets the external muscles more efficiently.","Lie face up on a Hack Squat machine with your shoulders against the pad.","Place your feet facing forward at a distance of 6 inches apart with your toes point slightly outward.","Release the dock levers and place your hands on the handgrips.","Drawing your abs in, extend your body standing upright.","Lower your body to a squatting position so your knees are bent as if you were sitting down.","Return to the starting position."]},{"slug":"narrow-stance-leg-press","title":"Narrow Stance Leg Press","idNum":"0143","type":"compound","primary":["quadriceps"],"secondary":["calves","hamstring"],"equipment":["machine"],"steps":["This is a variation of the leg press which targets more of the external muscles of the legs by moving your feet closer together.","Sit on a leg press machine with your feet on the crosspiece 6 inches apart, with your toes pointed slightly outward.","Grasp the handles on the side of the machine and release the locks.","Keeping your abs drawn in, bend your knees and bring the weight as far as possible towards your chest.","Hold this position for a moment and then slowly return the weight to starting position.","Note: Do not lock your knees at the top."]},{"slug":"narrow-stance-squat-with-barbell","title":"Narrow Stance Squat with Barbell","idNum":"0146","type":"compound","primary":["quadriceps"],"secondary":["glutes","calves","hamstrings"],"equipment":["barbell"],"steps":["A great overall exercise for the lower body. This version of the Squat targets and defines more of the externals leg muscles.","Lifting a barbell off of a weight rack, position it on your shoulders.","Place your feet about 6 inches apart with your knees and toes pointed slightly outward.","Drawing your abs in, descend slowly by bending at the knees and hips as if you are sitting down (squatting).","Lower yourself as far as you can control without letting your body shift towards your toes (this will cause you to loose balance).","Pause in the downward position and slowly return upright to the starting position.","Notes: A pad on the bar or towel on your shoulders can help improve your grip and reduce the discomfort of the bar against your back. Practice the squat without any weight to allow yourself to become comfortable with the movements."]},{"slug":"old-school-reverse-extensions","title":"Old School Reverse Extensions","idNum":"0185","type":"isolation","primary":["triceps"],"secondary":[],"equipment":["barbell"],"steps":["Lie down on a bench, on your back, with your head at one end.","Grasp a barbell with an underhand grip.","Move your arms beyond your head, keeping them in a straight line.","Bending only your elbows, slowly lower and raise the barbell."]},{"slug":"one-arm-barbell-floor-press","title":"One Arm Barbell Floor Press","idNum":"0070","type":"isolation","primary":["chest"],"secondary":["triceps"],"equipment":["barbell"],"steps":["Lie flat on your back with your knees bent and your feet firmly on the floor.","Draw in your abs and contract your lats, and glutes.","Have your partner hand you the bar and with your bicep parallel to the floor lift and extend your arm fully so it is straight.","Return to the starting position.","Complete reps and switch arms."]},{"slug":"one-arm-bench-press","title":"One Arm Bench Press","idNum":"0068","type":"isolation","primary":["chest"],"secondary":["triceps","shoulders"],"equipment":["flat bench","dumbbell"],"steps":["Lie flat on a bench with your feet placed firmly on the floor and your abs drawn in.","Grasp the dumbbell in one hand and bring it up to the side of your chest, this is starting position.","Extend your arm, pressing the dumbbell up till your arm is straight and your elbow locked.","Using slow controlled movements, lower the weight to starting position.","Switch arms after completing reps with one arm.","Repeat."]},{"slug":"one-arm-bicep-concentration-on-stability-ball-with-dumbbell","title":"One Arm Bicep Concentration on Stability Ball with Dumbbell","idNum":"0258","type":"isolation","primary":["biceps"],"secondary":["forearm"],"equipment":["dumbbell"],"steps":["Grasp a dumbbell in one hand and sit on a Stability Ball with your feet wide apart.","Bend forward leaning at the waist.","With the dumbbell in your hand, place your elbow against your knee.","Lower your arm so it is flat against your calves.","Curl your arm up to your chest keeping your elbow steady.","Return to starting position and change hands."]},{"slug":"one-arm-biceps-curl-with-olympic-bar-or-barbell","title":"One Arm Bicep Curl with Olympic Bar or Barbell","idNum":"0254","type":"isolation","primary":["biceps"],"secondary":["forearm"],"equipment":["barbell"],"steps":["Stand with your feet shoulder width apart and your knees slightly bent.","Grasp an Olympic bar (empty weight bar) in the middle with one hand so that the bar is equally balanced.","Keep your free hand at your side for support.","Curl the bar up so your forearm touches your bicep.","Slowly lower the bar and change arms.","Note: If an Olympic bar is too heavy use a lighter weight barbell."]},{"slug":"one-arm-dumbbell-shoulder-press","title":"One Arm Dumbbell Shoulder Press","idNum":"0038","type":"isolation","primary":["shoulders"],"secondary":["triceps","biceps"],"equipment":["dumbbell"],"steps":["Stand with your feet shoulder width apart, back straight and abs drawn in.","Grasp a dumbbell in your hand and lift it with a bent elbow to your shoulder height to start.","Lift the dumbbell straight up till your arm is fully extended overhead.","Lower in a controlled manner and return to starting position.","Repeat."]},{"slug":"one-arm-flat-bench-flys","title":"One Arm Flat Bench Fly’s","idNum":"0071","type":"isolation","primary":["chest"],"secondary":[],"equipment":["flat bench","dumbell"],"steps":["Lie on a flat bench with your free hand holding the bench.","Grasp the dumbbell in your other hand and with your forearm parallel to the floor raise your arm in an arc the middle of your chest.","Once the dumbbell is at the middle of your chest line, slowly lower is along the same path to starting position.","Repeat."]},{"slug":"one-arm-low-pulley-triceps-extension-with-cable","title":"One Arm Low-Pulley Triceps Extension with Cable","idNum":"0199","type":"compound","primary":["triceps"],"secondary":[],"equipment":["cable"],"steps":["Attach a handle to a low cable pulley machine.","Stand with your back to the weight stack, your feet shoulder width apart.","With your left hand, reach behind you and grasp the handle.","Place your right hand on your left elbow for support.","Extend your left arm straight up towards the ceiling and then lower it to the starting position.","Repeat and switch arms."]},{"slug":"one-arm-preacher-curl-with-dumbbell","title":"One Arm Preacher Curl with Dumbbell","idNum":"0237","type":"isolation","primary":["biceps"],"secondary":["forearm"],"equipment":["dumbbell"],"steps":["A Preacher Curl uses a special bench to support the triceps and isolate the biceps to build the arms. This version uses dumbbells and single arm movements for better control.","Adjust the seat of the bench so your arm is level with the top of the bench.","Grasp a dumbbell in your hand with palms facing up.","Rest your arm against the bench and extend it fully down.","Keeping your arm on the bench at all times, curl the dumbbell up towards your head.","Pause for a moment and then lower the dumbbell back to starting position.","Switch arms and repeat.","Note: Perform this exercise in a slow controlled manner for best results."]},{"slug":"one-arm-side-deadlift-with-barbell","title":"One Arm Side Deadlift with Barbell","idNum":"0150","type":"compound","primary":["quadriceps"],"secondary":["abdominals","glutes","calves","hamstrings"],"equipment":["barbell"],"steps":["This is an advanced exercise that works most of the muscles of the body. Exercises like this are used to develop functional strength for sports that require strong hands.","Stand besides a barbell placed on the floor.","Grasp the bar with an overhand grip in the center.","Crouching down as if your were performing a squat, bend down so your thighs are parallel with the floor.","Extend your legs slowly as you straighten your body up, drawing in your abs as you rise.","Note: Perform this exercise with an empty bar to become familiar with the movement before adding weights."]},{"slug":"one-arm-snatch-with-barbell","title":"One Arm Snatch with Barbell","idNum":"0148","type":"compound","primary":["quadriceps"],"secondary":["shoulders","hamstrings","lower back","abdominals","trapezius","calves"],"equipment":["barbell"],"steps":["This is an advanced exercise that works most of the muscles of the body. Exercises like this are used to develop functional strength for sports that require strong hands.","Stand with your feet shoulder width apart, and a slight bend in your knees.","Grasp the bar with an overhead grip.","Starting with the barbell held slightly above the knees (hang position), lift the weight up over your head (step 1) then back to shoulder height (step 2) and finally back to starting position between near your knees.","Note: Bend your knees as you lift and lower the weight to help control the movement."]},{"slug":"one-arm-tricep-extension-with-cable","title":"One Arm Tricep Extension with Cable","idNum":"0166","type":"isolation","primary":["triceps"],"secondary":[],"equipment":["cable"],"steps":["Place a cable pulley on the highest setting and adjust a stirrup handle to the pulley.","Stand facing the weight stack and grasp the handle with and underhand grip.","Keep your back straight, your abs drawn in and your knees slightly bent.","Starting at the top, push your arm down until it is straight, feeling the concentration in your tricep.","Slowly return to starting position.","Tips: Keep your elbow close to your side while performing this exercise."]},{"slug":"one-arm-triceps-extension-with-dumbbell","title":"One Arm Triceps Extension with Dumbbell","idNum":"0173","type":"isolation","primary":["triceps"],"secondary":[],"equipment":["dumbbell"],"steps":["Sit on a bench with your back straight and your abs drawn in.","Grasp a dumbbell in your hand and place it behind your neck with your elbow bent.","Slowly extend your arm straight up over your head and slowly return to the starting position.","Note: Place your free hand across your chest to help steady yourself during this exercise."]},{"slug":"one-arm-upright-row","title":"One Arm Upright Row","idNum":"0039","type":"isolation","primary":["shoulders"],"secondary":["trapezius"],"equipment":["dumbbell"],"steps":["Stand near a post or other stable tall object. With your one hand, hold the post.","Grasp the dumbbell in your other hand with a pronated grip (palms facing backwards).","Place the dumbbell in front of your thigh, this is starting position.","Lift the dumbbell upward to your shoulder with your elbow pointing away from your body in a rowing motion.","Lower your arm to starting position and repeat."]},{"slug":"one-armed-biased-push-up","title":"One Armed Biased Push Up","idNum":"0072","type":"isolation","primary":["chest"],"secondary":["triceps","bicpes","shoulders","core"],"equipment":["bosu ball"],"steps":["Arrange the ball so that as you begin the exercise, one hand on the Bosu ball and the other on the floor.","Place the ball flat side down on the floor.","Kneel on the floor with your arms fully extended on the dome, and body straight.","Keeping your abs drawn in and your body straight, lower your chest to the ball.","Pause for a moment and then return to starting position.","Repeat."]},{"slug":"one-leg-squat-with-barbell","title":"One Leg Squat with Barbell","idNum":"0147","type":"compound","primary":["quadriceps"],"secondary":["calves","hamstrings","glutes"],"equipment":["barbell"],"steps":["The One Leg Squat isolates the muscles of the leg for optimal exercise. This exercise is also used to build or rebuild strength after injury.","Place a bench or box 12-18 inches tall behind you. The taller the box the greater the difficulty of the exercise.","Lifting a barbell off of a weight rack, position it on your shoulders.","Place one foot up on the bench, and your other foot firmly on the floor 2-3 feet in front you.","Drawing your abs in descend slowly by bending your front knee and hip as if you are sitting down (squatting).","Lower yourself as far as you can control without letting your body shift towards your toe (this will cause you to loose balance).","Pause in the downward position and slowly return upright to the starting position.","Switch legs and repeat.","Notes: A pad on the bar or towel on your shoulders can help improve your grip and reduce the discomfort of the bar against your back. Practice the squat without any weight to allow yourself to become comfortable with the movements."]},{"slug":"one-legged-cable-kickback","title":"One Legged Cable Kickback","idNum":"0112","type":"isolation","primary":["gluts"],"secondary":["hamstring"],"equipment":["cable machine"],"steps":["Standing at a cable tower attach an ankle cuff to a low pulley.","Facing the weight stack, with a slight bend in your knees and your abs drawn in","Slowly kick your ankle back in and arc as high as you are able to.","Return to starting position and switch ankles."]},{"slug":"overhead-curl-with-cable","title":"Overhead Curl with Cable","idNum":"0238","type":"isolation","primary":["biceps"],"secondary":[],"equipment":["cable"],"steps":["By using cable this exercise isolates and defines the biceps (arm) muscles.","Attach a stirrup handle to each side of a high pulley on a cable machine.","Grasp the handles with palms facing up and stand with your feet shoulder width apart.","Extend your arms fully to each side.","Keeping your elbows steady, curl your wrists towards the sides of your head.","Contract your biceps and pause for a moment.","Then return to the starting position."]},{"slug":"overhead-squat-with-barbell","title":"Overhead Squat with Barbell","idNum":"0151","type":"compound","primary":["quadriceps"],"secondary":["glutes","calves","hamstrings","shoulders","lower back"],"equipment":["barbell"],"steps":["Stand with your feet a bit wider than shoulder width apart with your toes pointed slightly outward.","Grasp a barbell using a wide side snatch grip with your arms and elbows fully extended.","Keeping the bar overhead, bend your knees and lower your body until your thighs are parallel with the floor.","Return to starting position.","Notes: Keep your feet firmly planted on the floor throughout this exercise. Keep your abs drawn in your back tight and your chest up you perform this exercise."]},{"slug":"pile-squat-with-dumbbell","title":"Pile Squat with Dumbbell","idNum":"0152","type":"compound","primary":["quadriceps"],"secondary":["hamstrings","calves"],"equipment":["dumbbell"],"steps":["Stand with your feet 2-4 inches wider than your shoulders, with your toes pointed out at a 45 degree angle.","Grasp a dumbbell with both hands in the center of your body.","Keep your knees slightly bent and your back straight.","Squat down as if you were going to sit in a chair, bringing your thighs parallel to the floor.","With a controlled motion return to starting position.","Notes: Keep your feet planted firmly on the floor throughout this exercise."]},{"slug":"preacher-curl-with-barbell","title":"Preacher Curl with Barbell","idNum":"0239","type":"isolation","primary":["biceps"],"secondary":["forearm"],"equipment":["barbell"],"steps":["&nbsp;","Adjust the seat of the bench so that your arms are level with the top of the bench.","Grasp the bar with palms facing up, shoulder width apart.","Picking up the bar, rest your arms against the bench and extend them fully.","Keeping your arms on the bench at all times, curl the bar up towards your head.","Pause for a moment and then lower the bar back to starting position.","Note: Perform this exercise in a slow controlled manner for best results."]},{"slug":"preacher-curl-with-cable","title":"Preacher Curl with Cable","idNum":"0217","type":"isolation","primary":["biceps"],"secondary":["forearm"],"equipment":["cable"],"steps":["Place a padded arm curl bench in front of a cable machine.","Attach a short bar to the bottom pulley.","Rest your arms against the bench and extend them fully.","With a narrow grip (6 inches) grasp the bar with palms facing up and pull it towards your head.","Pause for a moment and then lower the bar back to starting position.","Note: Perform this exercise in a slow controlled manner for best results."]},{"slug":"preacher-curl-with-machine","title":"Preacher Curl with Machine","idNum":"0236","type":"isolation","primary":["biceps"],"secondary":["forearm"],"equipment":["machine"],"steps":["A Preacher Curl uses a special bench to support the triceps and isolate the biceps to build the arms. This version of the exercises is a machine exercise. This is a good exercise for beginners.","Adjust the seat of the bench so your arms are level with the top of the bench. Rest your arms against the bench and extend them fully. Grasp the bar underhand (palms facing up) and pull it towards your head. Pause for a moment and then lower the bar back to starting position.","Note: Perform this exercise in a slow controlled manner for best results. Read the instructions on the machine before performing this exercise."]},{"slug":"preacher-hammer-curl-with-dumbbell","title":"Preacher Hammer Curl with Dumbbell","idNum":"0240","type":"isolation","primary":["biceps"],"secondary":[],"equipment":["dumbbell"],"steps":["Adjust the seat of the bench so that your arms are level with the top of the bench.","Grasp a dumbbell in each hand with your palms facing each other, shoulder width apart and extend your arms fully along the bench.","Keeping your arms and elbows on the bench at all times, curl the dumbbells up towards your head.","Pause for a moment and then lower the bar back to starting position.","Note: Perform this exercise in a slow controlled manner for best results."]},{"slug":"prone-incline-biceps-curl-with-dumbbell","title":"Prone Incline Biceps Curl with Dumbbell","idNum":"0225","type":"isolation","primary":["biceps"],"secondary":[],"equipment":["dumbbell"],"steps":["This exercise uses an incline bench to change your body’s position as you perform Biceps Curls. The movement is very similar to a Preacher Curl.","Adjust an incline bench to a 45 degree angle.","Grasp dumbbells in each hand and lean face down against the bench, with your feet resting on the floor for support.","Allow your arms to hang down at your sides.","Keeping your elbow straight, raise the dumbbells up towards your head, contracting your biceps.","In a controlled manner, lower the weight and repeat.","Note: Practice steady movements in this exercise, be careful not to let your arms sway."]},{"slug":"pull-ups","title":"Pull Ups","idNum":"0087","type":"isolation","primary":["lats"],"secondary":["middle back","biceps"],"equipment":["bar"],"steps":["Grab the pull-up bar with the palms facing forward using the prescribed grip.","As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.","Pull your torso up until the bar touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this portion of the movement.","After a second on the contracted position, start to inhale and slowly lower your torso back to the starting position when your arms are fully extended and the lats are fully stretched.","Repeat this motion.","<h3> Tip</h3>","Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar."]},{"slug":"pullover-stability-ball-weight","title":"Pullover On Stability Ball With Weight","idNum":"0098","type":"isolation","primary":["shoulders"],"secondary":["back","neck"],"equipment":["exercise ball","dumbbell"],"steps":["Grasp a Barbell or Dumbbell and sit on a Ball with your feet firmly placed on the floor.","Lower your body so your upper abs are the only part of your body supported on the Ball.","Bring the Barbell or Dumbbell to your chest with your arms extend.","In an arcing motion raise the Barbell or Dumbbell over and behind your head towards the floor.","Return to starting position.","Repeat."]},{"slug":"push-up-feet-elevated","title":"Push Up with Feet Elevated","idNum":"0075","type":null,"primary":[],"secondary":[],"equipment":[],"steps":["This is the same general movement as with a Push Up except your feet are elevated allowing greater range of motions and targeting the pectorals differently than the regular Push Up.","Place your feet on a bench at least 18” off the ground.","Make sure the tops of your feet are flush against the bench.","Place your hands on the floor slightly wider than shoulder width apart.","With your hands directly under your shoulders, press up from the floor, keeping your back and neck in a straight line so you are looking forward during the entire exercise.","Once your arms are fully extended pause and then with slow controlled movements lower yourself to the floor again."]},{"slug":"push-ups","title":"Push Ups","idNum":"0077","type":"isolation","primary":["chest"],"secondary":["triceps","shoulders"],"equipment":["body"],"steps":["Start with a basic push up, lay face down on the floor, or a mat; with your feet together curled slightly so you rise onto the ball of your feet.","Place you hands shoulder width apart on the either side of your chest.","Draw your abs in.","Inhale as you raise your body up till your arms are straight.","Keep your head and neck level with your body (don’t look up or down) and don’t allow your back to rise or fall.","Exhale out as you lower your body back to the ground.","Repeat."]},{"slug":"push-ups-with-feet-on-exercise-ball","title":"Push Ups with feet on exercise ball","idNum":"0076","type":"isolation","primary":["chest"],"secondary":["triceps","shoulders"],"equipment":["body","exercise ball"],"steps":["Place your feet and shins flat on an Exercise Ball.","Place your arms in front of you at shoulder width apart, place your hands under your arms and press up from the ground until your arms are fully extended.","Pause at the top for a moment and steady your balance.","Slowly return to the starting position with your chest lowered towards the ground."]},{"slug":"quick-alternating-biceps-curls-with-band","title":"Quick Alternating Biceps Curls with Band","idNum":"0261","type":"isolation","primary":["biceps"],"secondary":["triceps"],"equipment":["band"],"steps":["Place a bungy under your feet and hold the handles palms forward in your hands.","Stand with your feet shoulder width apart, knees slightly bent and your abs drawn in.","Curl your arms up and down in an alternating motion, keeping your body straight.","As you become comfortable with the motion, increase your speed.","Note: Contract your biceps as you curl your arms up."]},{"slug":"rear-deltoid-row-barbell","title":"Rear Deltoid Row Barbell","idNum":"0028","type":"isolation","primary":["shoulders"],"secondary":["biceps"],"equipment":["barbell"],"steps":["Place a barbell on the floor in front of you with the resided weights attached.","With your knees bent and back straight grasp the bar with a wide overhand grip (palms facing downwards).","Keep your chest steady and your arms perpendicular to your chest.","Pull the bar as far up to your chest as you can.","Hold for a moment than lower the bar in a controlled manner.","Repeat."]},{"slug":"rear-deltoid-row-dumbbell","title":"Rear Deltoid Row Dumbbell","idNum":"0024","type":"isolation","primary":["posterior deltoid"],"secondary":["lateral deltoid","biceps","trapezius"],"equipment":["dumbbell"],"steps":["Place your right foot on the floor, rest your left knee and hand on a flat bench.","Lean forward so your body’s weight is supported by your left arm and knee.","Keeping your back flat, reach down and pick up the dumbbell with your right hand.","Raise your right arm as close to your chest as possible; while bending and bringing your elbow back as far as you can.","Pause at the top for a moment and then lower the dumbbell in a controlled manner to the starting position.","Switch arms by doing the opposite positioning.","Repeat."]},{"slug":"rear-lunges-with-barbell","title":"Rear Lunges with Barbell","idNum":"0128","type":"compound","primary":["quadriceps"],"secondary":["hip abductors","calves","gluts","hamstrings"],"equipment":["barbell"],"steps":["Place a barbell on a rack at chest height.","Lift the barbell of of the rack and onto your shoulders, gripping the bar slightly wider than shoulder width apart.","Stand with your feet approximately 8 inches apart with your toes pointing forward.","Slowly take a step backward with your right leg.","Keeping your abs drawn in and your upper body straight, lower your body until your left knee is almost on the ground. You may choose to place a mat or towel under your knee.","Hold for a moment and then return to starting position."]},{"slug":"rear-lunges-with-dumbbell","title":"Rear Lunges with Dumbbell","idNum":"0129","type":"compound","primary":["quadriceps"],"secondary":["calves","hamstrings","gluts","hip abductors"],"equipment":["dumbbells"],"steps":["This is an advanced version of a lunge.","Grasp a dumbbell in each hand.","Stand with your feet approximately 8 inches apart with your toes pointing forward.","Slowly take a step backward with your right leg.","Keeping your abs drawn in and your upper body straight, lower your body until your left knee is almost on the ground. You may choose to place a mat or towel under your knee.","Hold for a moment and then return to starting position."]},{"slug":"reverse-grip-triceps-pushdown","title":"Reverse Grip Triceps Pushdown","idNum":"0189","type":"isolation","primary":["triceps"],"secondary":[],"equipment":["cable"],"steps":["Stand in front of a cable machine and attach a bar to a high pulley.","Grasp the handle with palms facing up.","Keeping your elbows at your side, pull the handle down towards your thighs.","Pause for a moment and then return to the starting position.","Note: You may want to stager one foot in front of the other for a better stance."]},{"slug":"reverse-grips-bent-over-barbell-rows","title":"Reverse Grips Bent Over Barbell Rows","idNum":"0026","type":"isolation","primary":["middle back"],"secondary":["biceps"],"equipment":["barbell"],"steps":["Bend over a barbell at slight angle with your knees bent and your back straight.","Grasp the bar with a reverse grip (palms facing up) and slowly pull the barbell to your abs, keeping your elbows close to your sides.","Pause for a moment at the top.","Return the barbell to the starting position.","Repeat."]},{"slug":"reverse-plate-curls-with-weight","title":"Reverse Plate Curls with Weight","idNum":"0241","type":"isolation","primary":["biceps"],"secondary":["forearm"],"equipment":["weight plate"],"steps":["Stand with your feet shoulder width apart, your knees slightly bent and your abs drawn in.","Grasp a plate in your hands with palms facing down, at the 11:00 and 1:00 o’clock position.","Keeping your elbows and arms at your side, curl the slowly up towards your head.","Slowly return to the starting position."]},{"slug":"reverse-triceps-bench-press-with-barbell","title":"Reverse Triceps Bench Press with Barbell","idNum":"0190","type":"compound","primary":["triceps"],"secondary":["chest"],"equipment":["barbell"],"steps":["Lie on a flat bench with your head at one end and your feet placed firmly on the floor.","Grasp a barbell with palms facing your head about 16 inches apart.","Move the bar over your chest (about 1 inch below your nipples).","Extend your arms fully raising the bar fully and then lower the bar to the starting position."]},{"slug":"rocking-standing-calf-raise-with-barbell","title":"Rocking Standing Calf Raise with Barbell","idNum":"0278","type":"isolation","primary":["calves"],"secondary":[],"equipment":["barbell"],"steps":["Stand with a bar across your shoulders.","With your feet flat on the floor, lift your feet up and forward as if you are performing a calf raise.","Then “rock” back onto your ankles so your toes are flexed and off the floor.","Return to starting position.","Note: Wear running or cross training shoes while performing this exercise. Try performing this exercise without weight to become familiar with the movement,"]},{"slug":"romanian-dead-lift","title":"Romanian Dead Lift","idNum":"0118","type":"isolation","primary":["hamstrings"],"secondary":["calves","quadriceps","gluts"],"equipment":["barbell"],"steps":["Place a barbell in front of your feet on the ground.","Grasp the barbell with a grip a bit wider than shoulder width apart.","Bend your knees slightly, keeping your hips and back straight.","Lift the bar straight up concentrating on using your hips as you stand.","Stand with the bar resting against your thighs.","Lower the bar to the floor with a slight bend in your knees flexing your hips back for stability."]},{"slug":"seated-ab-crunch-with-cable","title":"Seated Ab Crunch with Cable","idNum":"0288","type":"isolation","primary":["abdominals"],"secondary":[],"equipment":["cable"],"steps":["Attach a rope to a high cable pulley.","Place a bench in front of cable weight stack.","Grasp the rope over your shoulders and sit with your back towards the stack.","With your feet firmly on the floor and keeping your hips steady, flex at the waist bringing your elbows towards your knees.","Return to the starting position.","Note: Perform this exercise in a slow controlled manner."]},{"slug":"seated-biceps-curl-with-dumbbell","title":"Seated Bicep Curl with Dumbbell","idNum":"0243","type":"isolation","primary":["biceps"],"secondary":["forearm"],"equipment":["dumbbell"],"steps":["Sit on bench with your feet firmly on the floor and your back straight.","Grasp a dumbbell in each hand with your palms facing each other.","Lower the dumbbells to your sides and slowly curl your arms up so your palms are facing up.","Squeeze your biceps at the top and slowly lower to the starting position.","Note: If possible use a short backed bench to help your posture."]},{"slug":"seated-cable-rows","title":"Seated Cable Rows","idNum":"0025","type":"compound","primary":["middle back"],"secondary":["biceps","lower back"],"equipment":["cable machine"],"steps":["Sit at a low pulley machine with your feet resting against the footrests and your knees slightly bent.","With your abs drawn in and your back straight lean forward slightly to grasp the pulleys with an overhand grip (palms face downwards).","Slowly bring the pulleys back towards your abs while sitting upright, keep your elbows in close to your chest.","Pause for a moment then return slowly return the pulleys to the starting position.","Repeat."]},{"slug":"seated-calf-raise-using-machine","title":"Seated Calf Raise using Machine","idNum":"0279","type":"isolation","primary":["calves"],"secondary":[],"equipment":["machine"],"steps":["Sit at a calf raise machine.","Put the balls of your feet on the footpad.","Place your thighs under the leg pad above your knees.","Unlock the bar and slowly raise your toes up as far as possible.","Pause for a moment and then return to the starting position.","Note: Practice slow and precise movements with this exercise."]},{"slug":"seated-calf-raise-with-barbell","title":"Seated Calf Raise with Barbell","idNum":"0272","type":"isolation","primary":["calves"],"secondary":[],"equipment":["barbell"],"steps":["Place a block on the floor about one foot in front of a bench.","Sit on the bench with a barbell across your upper thighs and the balls of your feet on the block.","Slowly raise and lower your toes up as high as possible without lifting your foot off the block."]},{"slug":"seated-close-grip-concentration-curls-with-barbell","title":"Seated Close Grip Concentration Curls with Barbell","idNum":"0242","type":"isolation","primary":["biceps"],"secondary":[],"equipment":["barbell"],"steps":["Concentration exercises limit your range of movement to increase the effectiveness of the movement. This version uses a barbell.","Sit on the end of a flat bench with your feet flat and your legs spread apart.","Bend forward at your waist keeping your back straight.","Grasp a barbell in your hands with a close grip approximately 6 inches apart with your palms facing up.","With your elbow pressed against your inner thigh, curl the bar up towards your chest.","Slowly lower the bar to the starting position near the floor.","Note: Keep all of your body still except the arm you are exercising."]},{"slug":"seated-leg-curl","title":"Seated Leg Curl","idNum":"0119","type":"isolation","primary":["hamstrings"],"secondary":[],"equipment":["machine"],"steps":["Adjust the machine so that the footpad is just above your heels.","Sit upright with your abs drawn in and your legs in front of you.","Slowly curl your legs back towards you and hold for a moment.","With controlled movement return to the starting position."]},{"slug":"seated-military-press","title":"Seated Military Press","idNum":"0004","type":"isolation","primary":["shoulders"],"secondary":["triceps"],"equipment":["barbell","bench"],"steps":["Sit on the bench with your toes pointing straight out, back straight and abs drawn in.","Grip the bar with your palms facing outwards and your hands shoulder width apart","With bar in front of your head, press upwards extending your arms but not locking them.","Pause at the top and then in a controlled movement lower the bar to the starting position."]},{"slug":"seated-one-arm-triceps-extension-with-dumbbell","title":"Seated One Arm Triceps Extension with Dumbbell","idNum":"0191","type":"isolation","primary":["triceps"],"secondary":[],"equipment":["dumbbell"],"steps":["Sit on the edge of a bench with your feet flat on the floor.","Hold a dumbbell in your right hand.","Bring your right arm up to your side so the dumbbell is almost parallel to your chest, keeping your lower arm vertical.","Press your arm back in arc.","Return to the starting position repeat and switch arms."]},{"slug":"seated-one-leg-calf-raise-with-dumbbell","title":"Seated One Leg Calf Raise with Dumbbell","idNum":"0276","type":"isolation","primary":["calves"],"secondary":[],"equipment":["dumbbell"],"steps":["This version of a calf raise allows you to exercise each leg individually. This exercise is helpful to people who are rehabilitating from injury as it allows you flexibility with the weight.","Place a block on the floor about one foot in front of a bench.","Sit on the bench with a dumbbell across your upper thigh and the balls of one foot on the block.","Slowly raise and lower your toe up as high as possible without lifting your foot off the block.","Switch feet and repeat."]},{"slug":"seated-overhead-triceps-extension-with-barbell","title":"Seated Overhead Triceps Extension with Barbell","idNum":"0193","type":"isolation","primary":["triceps"],"secondary":[],"equipment":["barbell"],"steps":["Sit on a short straight back chair with your feet firmly placed on the floor and your back straight.","Grasp an EZ or Curl bar, or barbell with a grip about 6 inches apart.","Raise the bar to arms length above your head and then lower the bar in an arc towards the floor behind your head.","Return to starting position."]},{"slug":"seated-rear-lateral-cable-raise","title":"Seated Rear Lateral Cable Raise","idNum":"0035","type":"isolation","primary":["shoulders"],"secondary":[],"equipment":["cable machine"],"steps":["Sit on the edge of a bench with your feet on the floor in front of you.","Rest your chest on your thighs with your back straight, grasp the cable pulleys with opposite hands.","Raise your upper arms to shoulder height. Pause at the top for a moment.","Lower your arms to the starting position in a controlled motion.","Repeat."]},{"slug":"seated-triceps-press-with-dumbbell","title":"Seated Triceps Press with Dumbbell","idNum":"0194","type":"isolation","primary":["triceps"],"secondary":[],"equipment":["dumbbell"],"steps":["Sit on a short, straight backed bench with your feet planted firmly on the floor.","Drawing your abs in, grasp the dumbbell with both hands with a palms up grip.","Raise the weight over your head, this is your starting position.","Lower the dumbbell in an arc from above your head to behind your back.","Slowly return to the starting position."]},{"slug":"seated-two-arm-triceps-extension-with-dumbbell","title":"Seated Two-Arm Triceps Extension with Dumbbell","idNum":"0192","type":"isolation","primary":["triceps"],"secondary":[],"equipment":["dumbbell"],"steps":["Sit on the edge of a bench with your feet flat on the floor.","Hold a dumbbell in each hand.","Bring your arms up to your side so the dumbbell is almost parallel to your chest, keeping your lower arm vertical.","Press your arm back in arc towards your back.","Return to the starting position repeat and switch arms."]},{"slug":"shoulder-shrugs","title":"Shoulder Shrugs","idNum":"0005","type":"isolation","primary":["trapezius"],"secondary":[],"equipment":["dumbbell"],"steps":["Stand with your feet shoulder width apart and a slight bend in your knees.","Hold a dumbbell in each hand and with your arms at your sides.","Lower your shoulders as much as possible.","With your arms straight raise both shoulders up towards your ears.","Hold the upright positions for a moment and then lower in a controlled motion."]},{"slug":"side-bend-with-dumbbell","title":"Side Bend with Dumbbell","idNum":"0294","type":"isolation","primary":["abdominals"],"secondary":[],"equipment":["dumbbell"],"steps":["Stand with your feet shoulder width apart, your knees slightly bent and your abs drawn in.","Grasp a dumbbell in one hand and standing straight upright, bend at the waist as far as possible to one side.","Slowly return back up to the staring position.","Switch the dumbbell to your other hand and repeat the exercise.","Note: Be careful to bend only at your waist and not at the hips or knees."]},{"slug":"side-plank","title":"Side Plank","idNum":"0113","type":"isolation","primary":["core"],"secondary":[],"equipment":["body"],"steps":["Lay on one side of your body with your legs straight and your forearm perpendicular to your body in front of you.","Drawing your abs in, slowly raise yourself up so you are balanced on your feet and your forearm.","Hold this position and slowly return back to the starting position.","Repeat on other side."]},{"slug":"side-squats-with-barbell","title":"Side Squats with Barbell","idNum":"0131","type":"compound","primary":["quadriceps"],"secondary":["hip abductors","hamstrings"],"equipment":["barbell"],"steps":["Place a barbell on your shoulders and grasp it with a wide grip.","Stand with your feet wide apart, with the foot of the leg you will be leaning towards angled out.","Bring your lower body to your foot by bending the hip and knee of your lead leg, and keeping your other leg fairly straight.","Return to the starting position and switch legs."]},{"slug":"single-arm-triceps-extension-with-dumbbell","title":"Single Arm Pronated Triceps Extension with Dumbbell","idNum":"0186","type":"isolation","primary":["triceps"],"secondary":[],"equipment":["dumbbell"],"steps":["This is an advanced exercise to isolate and work the tricep (back of the arm) muscles.","Lie flat in a bench with your head at one end and your feet placed firmly on the floor.","Grasp a dumbbell in one hand and raise it to a position above your chest, with your palm facing your feet.","Place your free hand under the shoulder to support your other arm.","Slowly lower the weight moving only your forearm and elbow towards and away from your chest.","Repeat with your other arm.","Note: Practice this exercise with light weight to get used to the movements."]},{"slug":"single-arm-supinated-triceps-extension-with-dumbbell","title":"Single Arm Supinated Triceps Extension with Dumbbell","idNum":"0187","type":"isolation","primary":["triceps"],"secondary":[],"equipment":["dumbbell"],"steps":["Lie flat in a bench with your head at one end and your feet placed firmly on the floor.","Grasp a dumbbell in one hand and raise it to a position above your chest, with your palm facing the floor.","Place your free hand under the shoulder to support your other arm. Slowly bend your elbow over your head with the weight moving only your forearm and elbow.","Return to the starting position and repeat with your other arm.","Note: Practice this exercise with light weight to get used to the movements."]},{"slug":"single-leg-squat-with-barbell","title":"Single Leg Squat with Barbell","idNum":"0132","type":"compound","primary":["quadriceps"],"secondary":["calves","hamstrings"],"equipment":["barbell"],"steps":["This is an advanced exercise and modification of the basic squat. Mastery of the squat is recommended before attempting this exercise.","Place a barbell on your back, above your shoulders with a wide grip.","Cross the lower leg above the knee of your supporting leg (the leg you will squat with).","Squat down as low as you are able.","Slowly return to an upright position by straightening your hip and knee.","Switch legs and repeat."]},{"slug":"smith-machine-bench-press","title":"Smith Machine Bench Press","idNum":"0078","type":"isolation","primary":["chest"],"secondary":["shoulders","triceps"],"equipment":["flat bench","smith machine"],"steps":["Place a flat bench in the middle of the Smith Machine, with the bar in line with the middle of your chest.","Lying on the bench, grasp the bar at shoulder width apart.","Unlatch the bar and slowly lower the bar to your chest.","Extend your arms fully and raise the bar to the starting position.","Repeat."]},{"slug":"smith-machine-close-grip-bench-press","title":"Smith Machine Close Grip Bench Press","idNum":"0195","type":"compound","primary":["triceps"],"secondary":["chest"],"equipment":["smith machine"],"steps":["Place a flat bench in the middle of a Smith Machine.","Using a close grip (about 6 inches apart) unlatch the bar and lower it towards your chest.","Pause just before the bar hits your chest and raise the bar by extending your arms to the starting position."]},{"slug":"smith-machine-dead-lifts","title":"Smith Machine Dead Lifts","idNum":"0100","type":"isolation","primary":["lower back"],"secondary":["hamstrings","calves"],"equipment":["smith machine"],"steps":["Stand with your feet shoulder width apart so that your feet are under the bar.","Keeping your back straight bend at the waist, allow some bend in your knees.","Grasp the par with an overhand grip approximately 16 inches apart.","Straighten your back as you hold the bar at arm’s length.","Bend over again lowering the bar to just above the floor."]},{"slug":"smith-machine-good-mornings","title":"Smith Machine Good Mornings","idNum":"0102","type":"isolation","primary":["lower back"],"secondary":["hamstrings"],"equipment":["smith machine"],"steps":["Place a barbell across your shoulders.","Keeping your head up and your back completely straight, bend at the waist until your back is parallel with the floor.","Return to starting position.","Repeat."]},{"slug":"smith-machine-hack-squat","title":"Smith Machine Hack Squat","idNum":"0126","type":"compound","primary":["quadriceps"],"secondary":["hamstrings","gluts"],"equipment":["smith machine"],"steps":["This is another variation of the basic Squat that focuses primarily on the quadriceps, or thigh muscles, while using the Smith Machine.","Adjust the bar to a low setting just above your ankles.","Stand with the bar on the floor just behind your legs, with your feet shoulder width apart and your toes pointing forward.","With your feet firmly placed on the floor reach down and grasp the bar from behind, with an overhand grip.","Lift the bar by extending your hips and knees, taking care not to lock your knees.","Lower yourself (squat) down until your thighs are parallel to the floor.","Slowly raise yourself up to starting position.","Note: Your knees should be moving in the same direction as your feet."]},{"slug":"smith-machine-incline-bench-press","title":"Smith Machine Incline Bench Press","idNum":"0081","type":"isolation","primary":["chest"],"secondary":["shoulders","triceps"],"equipment":["smith machine","incline bench"],"steps":["Place an incline bench at a 45 degree angle in the middle of the Smith Machine.","Align the bench so the bar is across the upper portion of your chest.","Grasp the bar with a shoulder width grip.","Unlock the bar and slowly lower the weight to your chest, do not bounce the bar on your chest.","With slow controlled movements, raise the bar back to the starting position."]},{"slug":"smith-machine-rear-deltoid-row","title":"Smith Machine Rear Deltoid Row","idNum":"0022","type":"isolation","primary":["rear deltoid"],"secondary":["back","biceps","shoulders"],"equipment":["smith machine"],"steps":["This is an exercise for rear deltoid,shoulder, biceps and back strengthening."," Set the bar to the lowest setting.","Place your feet shoulder width apart with a slight bend in the knees.","Bend at the waist while keeping your back straight and chest parallel to the floor.","Grasp the bar slightly wider than your shoulders with an overhand grasp and your arms straight with a slight bend in the elbows.","Raise the bar with a controlled motion to the lower part of your chest by bending and elevating your elbows.","Hold for a moment and then lower to the starting position.","Repeat."]},{"slug":"smith-machine-reverse-calf-raises","title":"Smith Machine Reverse Calf Raises","idNum":"0280","type":"isolation","primary":["calves"],"secondary":[],"equipment":["smith machine"],"steps":["Place a block or low box under the bar at a Smith Machine.","Stand on the edge of the box with your toes hanging off.","Place the bar across your shoulders and lean forward lifting your ankles off the box.","Return to the starting position.","Note: Use the bar for support as you perform this exercise."]},{"slug":"smith-machine-shoulder-shrugs","title":"Smith Machine Shoulder Shrugs","idNum":"0041","type":"isolation","primary":["shoulders"],"secondary":[],"equipment":["smith machine"],"steps":["Place the barbell at waist height.","Stand with your feet shoulder width apart and your abs drawn in.","Grasp the bar with an overhand grip and straightened arms.","As you lift the bar allow the weight to pull your shoulders down, shrug your shoulders up and to the back.","Hold for a moment and then return to starting position."]},{"slug":"smith-machine-squats","title":"Smith Machine Squats","idNum":"0124","type":"compound","primary":["quadriceps"],"secondary":["calves","gluts","hamstrings"],"equipment":["smith machine"],"steps":["This exercise uses the Smith Machine to work the Quadriceps, Hamstrings, Calves and Glutes. A great overall exercise for the lower body. There are many variations on the squat, this is the original version using a Smith Machine for better flow of movement.","Set the height of the barbell to shoulder height.","Place your feet slightly wider than shoulder width apart with your knees and toes pointed slightly outward.","Drawing your abs in descend slowly by bending at the knees and hips as if you are sitting down (squatting).","Lower yourself as far as you can control without letting your body shift over your toes (this will cause you to loose balance).","Pause in the downward squatting position and slowly return upright to the starting position.","If needed, a pad on the bar or towel on your shoulders can help improve your grip and the reduce the discomfort of the bar against your back. First practice the squat without any weight to allow yourself to become comfortable with the movements."]},{"slug":"smith-machine-upright-row","title":"Smith Machine Upright Row","idNum":"0013","type":"isolation","primary":["shoulders"],"secondary":["biceps","upper back"],"equipment":["smith machine"],"steps":["Stand with your feet shoulder width apart and your abs drawn in.","Place the bar on the Smith Machine in the position where your arms are fully extended in front of you.","Place your hands shoulder width apart and raise the bar up towards your chin with a controlled motion.","Pause at the top for a moment and rotate your shoulder blades together.","Lower the bar to the starting position."]},{"slug":"speed-squats-with-barbell","title":"Speed Squats with Barbell","idNum":"0154","type":"compound","primary":["quadriceps"],"secondary":["calves","glutes","hamstrings"],"equipment":["barbell"],"steps":["This version of the squat uses an empty barbell and moves at a faster pace than the standard squat. This is a good exercise for building speed and conditioning used in running and jumping sports.","Place your feet slightly wider than shoulder width apart with your knees and toes pointed slightly outward.","Drawing your abs in, descend slowly by bending at the knees and hips as if you are sitting down (squatting).","Lower yourself as far as you can control without letting your body shift towards your toes (this will cause you to loose balance).","Pause in the downward position and slowly return upright to the starting position.","Note: Keep your feet firmly planted on the floor throughout this exercise."]},{"slug":"spider-curl-with-barbell","title":"Spider Curl with Barbell","idNum":"0245","type":"isolation","primary":["biceps"],"secondary":[],"equipment":["barbell"],"steps":["This exercise uses the straight side of a Preacher Curl bench to increase the range of motion of the exercise.","Turn a Preacher Curl bench around so you are leaning against the angled side.","Grasp a barbell with palms up, approximately 6 inches apart.","Leaning against the bench, lower the bar along the flat side of the bench fully extending your arms.","Curl your arms up so your biceps are touching your forearms.","Slowly lower the bar to the starting position.","Note: Use a low weight to get used to the motion of this exercise."]},{"slug":"squat-to-bench-with-barbell","title":"Squat to Bench with Barbell","idNum":"0133","type":"compound","primary":["quadriceps"],"secondary":["gluts","calves","hamstrings"],"equipment":["barbell"],"steps":["This is s great overall exercise for the lower body. There are many variations on the squat, this one uses a bench to remind you how far down to squat.","Place a bench behind you.","Lifting a barbell off of a weight rack, position it on your shoulders.","Place your feet slightly wider than shoulder width apart with your knees and toes pointed slightly outward.","Drawing your abs in, descend slowly and squat down, bending at the knees and hips.","Lower yourself as far as you can control without letting your body shift towards your toes (this will cause you to loose balance). Do not sit on the bench.","Pause in the downward position and slowly return upright to the starting position.","A pad on the bar or towel on your shoulders can help improve your grip and reduce discomfort of the bar against your back. Practice the squat without any weight to allow yourself to become comfortable with the movements. Do not sit on the bench during the exercise."]},{"slug":"squat-to-bench-with-dumbbells","title":"Squat to Bench with Dumbbells","idNum":"0136","type":"compound","primary":["quadriceps"],"secondary":["calves","hamstring","gluts"],"equipment":["dumbbell"],"steps":["This is a great overall exercise for the lower body. There are many variations on the squat, this one uses a bench to remind you how far down to squat.","Place a bench behind you.","Grasp a dumbbell in each hand.","Place your feet slightly wider than shoulder width apart with your knees and toes pointed slightly outward.","Drawing your abs in descend slowly by squatting down and bending at the knees and hips.","Lower yourself as far as you can control without letting your body shift towards your toes (this will cause you to loose balance).","Pause in the downward position and slowly return upright to the starting position.","Practice the squat without any weight to allow yourself to become comfortable with the movements. Do not sit on the bench during the exercise."]},{"slug":"squats-using-dumbbells","title":"Squats using Dumbbells","idNum":"0130","type":"compound","primary":["quadriceps"],"secondary":["hamstring","calves"],"equipment":["dumbbells"],"steps":["This is a great overall exercise for the lower body that uses dumbbells instead of a barbell. Beginners may find this version easier to perform.","Grasp a dumbbell in each hand.","Stand with feet slightly wider than shoulder width apart with your knees and toes pointed slightly outward.","Drawing your abs in descend slowly by bending at the knees and hips as if you are sitting down (squatting).","Lower yourself as far as you can control without letting your body shift towards your toes (this will cause you to loose balance).","Pause in the downward position and slowly return upright to the starting position.","Note: Practicing the squat without any weight will allow you to become comfortable with the movements."]},{"slug":"squats-with-exercise-bands","title":"Squats with Exercise Bands","idNum":"0155","type":"compound","primary":["quadriceps"],"secondary":["calves","glutes","hamstrings"],"equipment":["exercise band"],"steps":["Stand with your feet on the exercise bands with your feet shoulder width apart.","Grasp the handles of the bands and pull them up to your shoulders.","With your abs drawn in, squat down until your thighs are parallel with the floor.","Slowly return to the starting position.","Note: Keep your feet firmly planted on the floor throughout this exercise."]},{"slug":"stability-ball-abdominal-crunch","title":"Stability Ball Abdominal Crunch","idNum":"0295","type":"isolation","primary":["abdominals"],"secondary":[],"equipment":["body"],"steps":["This crunch uses a Stability Ball. The ball allows you a better range of movement because it adapts better to your spine.","Sit on top of an exercise or stability ball with your feet placed firmly on the floor for support.","Position yourself so that your lower back is centered on the middle of the ball.","Lie back and bring your hands across your chest, or on either side of your head (over your ears).","Raise your head, chest and shoulders up crunching your abs as you sit upright.","Pause for a moment and then lower yourself to the starting position.","Note: For best results, use a full range of motion in this exercise."]},{"slug":"standing-barbell-calf-raise","title":"Standing Barbell Calf Raise","idNum":"0281","type":"isolation","primary":["calves"],"secondary":[],"equipment":["barbell"],"steps":["Place a block or two free weight plates on the floor.","Place a barbell across your back and step up so the balls of your feet are on the block.","Slowly lift your heels up and then lower them back to the floor getting as much of a stretch as possible.","Return to starting position."]},{"slug":"standing-biceps-curl-with-cable","title":"Standing Biceps Curl with Cable","idNum":"0212","type":"isolation","primary":["biceps"],"secondary":["forearm","shoulders"],"equipment":["cable"],"steps":["Attach a short bar to a cable pulley to the bottom of the weight stack.","Stand with your feet shoulder width apart, your knees slightly bent and your abs drawn in.","Grasp the bar with palms facing up, and hands fairly close together.","Lower your arms fully to above your thighs and bending only your elbows, raise the bar to your upper chest.","Pause for a moment and then return to the starting position.","Note: Do not swing your hips or back during this exercise."]},{"slug":"standing-calf-raises-using-machine","title":"Standing Calf Raises using Machine","idNum":"0282","type":"isolation","primary":["calves"],"secondary":[],"equipment":["machine"],"steps":["This exercise uses a machine to allow for proper form.","Stand with your toes on the footpad of the machine and adjust your shoulders under the upper pads.","Raise up on the balls of your feet, lifting your heels off the pad.","Hold for a moment and then return to the starting position."]},{"slug":"standing-inner-biceps-curl-with-dumbbell","title":"Standing Inner Biceps Curl with Dumbbell","idNum":"0246","type":"isolation","primary":["biceps"],"secondary":["forearm"],"equipment":["dumbbell"],"steps":["Stand with your feet shoulder width apart, your knees slightly bent and your abs drawn in.","Grasp a dumbbell in each arm with your palms facing each other, fully extend your arms along your sides.","Curl your arms up and out, turning your palms up and out as you lift.","Slowly lower the dumbbells to the starting position.","Note: Try to keep your forearms in line with your shoulders as you lift the weight."]},{"slug":"standing-leg-curls","title":"Standing Leg Curls","idNum":"0120","type":"isolation","primary":["hamstrings"],"secondary":[],"equipment":["machine"],"steps":["Standing at a leg curl machine adjust the rear footpad so it is just above your ankle.","Grasp the handles of the machine for support and draw your abs in.","Raise your foot up towards your back slowly.","Return to the starting position and chance legs."]},{"slug":"standing-one-arm-biceps-curl-with-cable","title":"Standing One Arm Bicep Curl with Cable","idNum":"0247","type":"isolation","primary":["biceps"],"secondary":["forearm"],"equipment":["cable"],"steps":["This is a single arm version of a bicep cable curl. Cable machines are great for helping you learn proper form while building muscle.","Attach a stirrup bar to a low cable pulley.","Stand of the side of the weight stack with your legs shoulder width apart and your knees slightly bent and your abs drawn in.","Grasp the stirrup in one hand with an palms facing up.","Lower the stirrup to the top of your thighs.","Keeping your elbows still, curl the stirrup up towards your chest.","Slowly lower the stirrup to the starting position."]},{"slug":"standing-one-arm-curl-over-incline-bench-with-dumbbell","title":"Standing One Arm Curl Over Incline Bench with Dumbbell","idNum":"0248","type":"isolation","primary":["biceps"],"secondary":["forearm"],"equipment":["dumbbell"],"steps":["This exercise is a great alternative to the Preacher Curl.","Stand in front of an incline bench so your arm is resting on the top of the angled portion of the bench.","Grasp a dumbbell in your hand with palms facing up.","Rest your arm against the back bench and extend it fully down.","Keeping your arm on the bench at all times, curl the dumbbell up towards your head.","Pause for a moment and then lower the dumbbell back to starting position.","Switch arms and repeat.","Note: Perform this exercise in a slow controlled manner for best results."]},{"slug":"standing-overhead-triceps-extension-with-barbell","title":"Standing Overhead Triceps Extension with Barbell","idNum":"0201","type":"isolation","primary":["triceps"],"secondary":[],"equipment":["barbell"],"steps":["Stand with your feet shoulder width apart, your back straight and your abs drawn in.","Hold a barbell or EZ Curl bar about 6-8 inches apart with your palms facing up.","Raise the bar over your head and slowly lower the dumbbell in an arc behind your head, towards your back.","Slowly raise the bar back up to the starting position.","Note: Keep your elbows close to your head during the exercise"]},{"slug":"standing-triceps-extension-2","title":"Standing Triceps Extension","idNum":"0198","type":"isolation","primary":["triceps"],"secondary":[],"equipment":["dumbbell"],"steps":["Stand with your feet shoulder width apart, your back straight and your abs drawn in.","Hold a dumbbell in both hands, with your palms facing up.","Raise the dumbbell over your head and slowly lower the dumbbell in an arc behind your head.","Slowly raise the dumbbell back up to the starting position.","Note: Keep your elbows close to your head during the exercise."]},{"slug":"standing-triceps-extension-with-towel","title":"Standing Triceps Extension with Towel","idNum":"0202","type":"isolation","primary":["triceps"],"secondary":[],"equipment":["body"],"steps":["Stand with your feet shoulder width apart, your back straight and your abs drawn in.","Hold a towel or rope facing up behind and in back of your head.","Have a partner hold the towel taught during the exercise so the resistance is constant.","Lower your forearms down until they reach your biceps, then slowly raise your arms back up to starting position.","Note: Keep your elbows close to your head during the exercise."]},{"slug":"static-neck-flexion-extension","title":"Static Neck Flexion and Extension","idNum":"0001","type":"isometric","primary":["neck extensors","neck flexors"],"secondary":[],"equipment":["body"],"steps":["An exercise to either build or warm-up front and back neck muscles.","Stand or sit with your head in neutral position.","Place both of your hands on your forehead.","Press your head against your hands and contract your neck muscles.","Keep your head from moving forward. Hold for at least 30 seconds.","Repeat with hands on the back of your head, pressing against them."]},{"slug":"static-neck-side-flexion","title":"Static Neck Side Flexion","idNum":"0002","type":"isometric","primary":["neck side flexors"],"secondary":[],"equipment":["body"],"steps":["Stand or sit with your head in neutral position.","Place your left hand against the left side of your head, above your ear.","Push your head against your hand, without moving your head.","Repeat with your right hand, right side of your head."]},{"slug":"stationary-abdominal-draw-in","title":"Stationary Abdominal Draw In","idNum":"0027","type":"isometric","primary":["abdominals"],"secondary":["core"],"equipment":["body"],"steps":["Get down on a mat on your hands and knees, forming a four point rectangle or square shape.","Keep your back straight and your hips and pelvis in a neutral position.","Draw your abs in, crunching your abs while keeping your back still.","Hold for a moment and then release returning to the starting position.","Repeat."]},{"slug":"step-up-single-leg-balance-with-biceps-curl-using-dumbbells","title":"Step Up Single Leg Balance with Bicep Curl using Dumbbells","idNum":"0266","type":"isolation","primary":["biceps"],"secondary":["core","quadriceps","forearm","hamstrings","glutes","calves"],"equipment":["dumbbell"],"steps":["This is an advanced exercise. This exercise combines a step up with a bicep curl.","Place a box or bench in front of you.","Place a dumbbell in each hand with palms facing up.","Keep your back straight, your shoulders back and your abs drawn in.","With one leg, step up on to the box and raise your other leg up (as if taking another step).","At the top of the step, curl your arms up by bringing your biceps towards your shoulders.","Return to the starting position and switch legs."]},{"slug":"step-ups-with-barbell","title":"Step Ups with Barbell","idNum":"0134","type":"compound","primary":["quadriceps"],"secondary":["hamstrings","calves"],"equipment":["barbell"],"steps":["Place a bench, box or step in front of you.","Grasp a barbell with a wide grip and place it across your shoulders.","With your left leg, step up on the bench, and follow by stepping up with your right leg.","Step down with your left leg and then your right leg.","Repeat starting with your right leg.","Note: Use a lighter weight until you are used to the motion of this exercise."]},{"slug":"step-ups-with-dumbbells","title":"Step Ups with Dumbbells","idNum":"0137","type":"compound","primary":["quadriceps"],"secondary":["calves","hamstrings"],"equipment":["dumbbells"],"steps":["Place a bench, box or step in front of you.","Grasp a dumbbell in each hand.","With your left leg, step up on the bench, and follow by stepping up with your right leg.","Step down with your left leg and then your right leg.","Repeat starting with your right leg.","Note: Use a lighter weight until you are used to the motion of this exercise."]},{"slug":"stork-stance-biceps-curl-with-dumbbells","title":"Stork Stance Bicep Curl with Dumbbells","idNum":"0268","type":"isolation","primary":["biceps"],"secondary":["quadriceps","hamstrings","glutes","calves","triceps"],"equipment":["dumbbell"],"steps":["Grasp a pair of dumbbells in each hand, palms facing up.","Standing on one foot, extend your other foot back (see illustration) and extend your arms down so they are handing in front of your leg.","While on one foot, curl your arms up contracting your biceps.","Return to the starting position and switch legs.","Note: Have a Personal Trainer or Instructor show you how to properly perform this exercise."]},{"slug":"straight-arm-dumbbell-pullover","title":"Straight Arm Dumbbell Pullover","idNum":"0079","type":"isolation","primary":["chest"],"secondary":["triceps","lats","shoulders"],"equipment":["flat bench","dumbbell"],"steps":["Lie on a flat bench with your feet flat on the floor and your head at the end of the bench.","Grasp a dumbbell and raise it over your chest.","Keeping your elbows as straight as possible, lower the weight in an arc over your head and as low to the ground as possible with out any pain.","Return to starting position.","Repeat."]},{"slug":"straight-arm-push-down","title":"Straight Arm Push Down","idNum":"0092","type":"isolation","primary":["lats"],"secondary":["triceps"],"equipment":["cable machine"],"steps":["Grasp wide grip pull down bar with a wide grip so your hands are on the portion of the bar which curves down.","Stand erect with your abs drawn in.","Keeping a slight bend in your elbows and your wrist steady pull the bar down from the starting position to your upper thighs.","With a controlled motion bring the bar back up to starting position."]},{"slug":"supermans","title":"Supermans","idNum":"0105","type":"isolation","primary":["lower back"],"secondary":["core"],"equipment":["body"],"steps":["Lie flat on your stomach with your arms stretched out in front of you.","Raise your arms and legs off the floor and hold this position for 2 seconds.","Return to the starting position on the floor.","Repeat."]},{"slug":"t-bar-rows","title":"T-Bar Rows","idNum":"0029","type":"isolation","primary":["middle back"],"secondary":["biceps","shoulders"],"equipment":["t-bar machine"],"steps":["Place your feet on either side of a T-Bar Machine.","With your knees slightly bent and abs drawn in, grasp the handles with a narrow grip.","Bend at the waist so your chest is parallel to the floor, this is starting position. Slowly pull the bar to your chest, as high as you can.","Pause at the top for a moment and then lower the bar to starting position.","Repeat"]},{"slug":"tate-press","title":"Tate Press","idNum":"0020","type":"isolation","primary":["triceps"],"secondary":[],"equipment":["dumbbell"],"steps":["Lay flat on a bench with your head at one end and your feet firmly planted on the floor.","Hold a dumbbell in each hand so your palms are faced towards your feet.","Drawing your abs in and keeping your back on the bench, raise the weights to the center of your chest.","Without moving elbows, slowly raise your arms up and out contracting your triceps."]},{"slug":"tate-press-with-dumbbell","title":"Tate Press with Dumbbell","idNum":"0203","type":"isolation","primary":["triceps"],"secondary":[],"equipment":["dumbbell"],"steps":["Lay flat on a bench with your head at one end and your feet firmly planted on the floor.","Hold a dumbbell in each hand so your palms are facing your feet.","Drawing your abs in and keeping your back on the bench, raise the weights to the center of your chest.","Without moving elbows, slowly raise your arms up and out contracting your triceps."]},{"slug":"thigh-abductor","title":"Thigh Abductor","idNum":"0156","type":"isolation","primary":["quadriceps"],"secondary":["hamstrings"],"equipment":["machine"],"steps":["Sit on the machine and place your knees against the pads.","Draw your abs in and “abduct” or move your thighs apart against the pads.","Slowly return to the starting position and repeat.","Note: Maintain the same level of resistance throughout this exercise for best results."]},{"slug":"thigh-adductor","title":"Thigh Adductor","idNum":"0157","type":"isolation","primary":["quadriceps"],"secondary":["hamstrings"],"equipment":["machine"],"steps":["Sit on the machine and place your knees against the pads.","Draw your abs in and “adduct” or move your thighs together.","Slowly return to the starting position and repeat.","Note: Maintain the same level of resistance throughout this exercise for best results."]},{"slug":"tricep-dips-using-body-weight","title":"Tricep Dips using Body Weight","idNum":"0172","type":"compound","primary":["triceps"],"secondary":["shoulders","chest"],"equipment":["body"],"steps":["Grasp a set of parallel bars and push yourself up to the starting position.","Keeping your elbows close to your body, lower yourself down until your triceps are parallel to the floor.","Slowly raise yourself back to the starting position.","Note: Keep your abs drawn in and your body straight during this exercise."]},{"slug":"tricep-dips","title":"Tricep Dips using Machine","idNum":"0171","type":"compound","primary":["triceps"],"secondary":["shoulders"],"equipment":["machine"],"steps":["Adjust the seat of the machine so that the handles are equal with your elbows.","Grasping the handles, press down with equal pressure until your arms are fully extended.","Pause, and then return to the starting position."]},{"slug":"triceps-extensions-using-machine","title":"Triceps Extensions using Machine","idNum":"0210","type":"isolation","primary":["triceps"],"secondary":[],"equipment":["machine"],"steps":["Name: This exercise uses a machine to insure proper range of motion. This is a good exercise for beginners and people rehabilitating from injury.","Adjust the seat height of the machine so your upper arms and elbows lie flat on the pad. Draw your abs in and sit upright with your back straight. With your arms fully extended grasp the handles and pull them towards your body. Hold for a moment and then slowly return to the starting position.","Note: Stay seated and keep your feet firmly on the floor throughout this exercise."]},{"slug":"triceps-kickback-with-dumbbell","title":"Triceps Kickback with Dumbbell","idNum":"0204","type":"isolation","primary":["triceps"],"secondary":[],"equipment":["dumbbell"],"steps":["Standing along side a flat bench, bend your left knee and place it on the bench.","Place your left hand on the bench for support, keeping your back at a 45 degree angle.","Hold a dumbbell in your right hand and place your right foot on the floor.","Bend your right arm and raise it up to your shoulder, then with controlled motion kick it back, fully extending your arm.","Switch arms and repeat.","Note: Keep your elbow close to your body during this exercise."]},{"slug":"triceps-pushdown-with-cable","title":"Triceps Pushdown with Cable","idNum":"0205","type":"isolation","primary":["triceps"],"secondary":[],"equipment":["cable"],"steps":["Stand in front of a cable machine and attach a short bar to a high pulley.","Grasp the handle with your palms facing down.","Draw your abs in and keep your back straight.","Keeping your elbows at your side push the handle down towards your thighs.","Pause for a moment and then return to the starting position.","Note: You may want to stager one foot in front of the other for a better stance."]},{"slug":"triceps-pushdown-with-rope-and-cable","title":"Triceps Pushdown with Rope and Cable","idNum":"0206","type":"isolation","primary":["triceps"],"secondary":[],"equipment":["cable"],"steps":["Stand in front of a cable machine and attach a rope to a high pulley.","Grasp the rope with palms facing down.","Draw your abs in and keep your back straight.","Keeping your elbows at your side push the rope down towards your thighs, if possible “split” the rope apart at the bottom.","Pause for a moment and then return to the starting position.","Note: You may want to stager one foot in front of the other for a better stance."]},{"slug":"triceps-pushdown-with-v-bar-and-cable","title":"Triceps Pushdown with V Bar and Cable","idNum":"0207","type":"isolation","primary":["triceps"],"secondary":[],"equipment":["cable","v-bar"],"steps":["This exercise is the triceps pushdown uses a V shaped bar. Many people find this version easier on the elbows.","Steps","Stand in front of a cable machine and attach a V Bar to a high pulley.","Grasp the bar with palms facing down.","Draw your abs in and keep your back straight.","Keeping your elbows at your side push the bar down towards your thighs.","Pause for a moment and then return to the starting position.","Note: You may want to stager one foot in front of the other for a better stance."]},{"slug":"two-arm-preacher-curl-with-dumbbell","title":"Two-Arm Preacher Curl with Dumbbell","idNum":"0249","type":"isolation","primary":["biceps"],"secondary":["forearm"],"equipment":["dumbbell"],"steps":["A Preacher Curl uses a special bench to support the triceps and isolate the biceps to build the arms. This version of the exercise uses dumbbells.","Adjust the seat of the bench so your arms are level with the top of the bench.","Grasp a dumbbell in each hand with palms facing up.","Picking up the dumbbells, rest your arms against the bench and extend them fully towards the floor.","Keeping your arms on the bench at all times, curl the weight up towards your head.","Pause for a moment and then lower the weights back to starting position.","Note: Perform this exercise in a slow controlled manner for best results."]},{"slug":"underhand-pull-down","title":"Underhand Pull down","idNum":"0095","type":"isolation","primary":["lats"],"secondary":["biceps"],"equipment":["cable machine"],"steps":["Sitting upright with your abs drawn in grasp a Pull Down bar with and underhand grip shoulder width apart.","Pull the bar down till the bar reaches your upper chest, keeping your elbows close to your body.","Slowly return the bar to the starting position.","Repeat."]},{"slug":"underhand-pull-downs","title":"Underhand Pull downs","idNum":"0093","type":"isolation","primary":["lats"],"secondary":["biceps"],"equipment":["cable machine"],"steps":["Sitting upright with your abs drawn in grasp a Pull Down bar with and underhand grip shoulder width apart.","Pull the bar down till the bar reaches your upper chest, keeping your elbows close to your body.","Slowly return the bar to the starting position.","Repeat."]},{"slug":"upright-band-rows","title":"Upright Band Rows","idNum":"0094","type":"isolation","primary":["lats"],"secondary":["triceps","shoulders"],"equipment":["body","bands"],"steps":["Stand on the band so that the handles are level with your upper thigh.","With your back straight and abs drawn in raise your hands upward to your collarbone.","Your elbows and arms should be parallel with the floor.","Slowly lower your arms and return to starting position."]},{"slug":"upright-barbell-rows","title":"Upright Barbell Rows","idNum":"0014","type":"isolation","primary":["shoulders"],"secondary":["biceps","upper back"],"equipment":["barbell"],"steps":["Stand with your feet shoulder width apart, your abs drawn in and back straight.","Place the bar on rack in the position where your arms are fully extended in front of you with your elbows slightly bent.","Place your hands shoulder width apart and raise the bar up towards your chin with a controlled motion.","Pause at the top for a moment and rotate your shoulder blades together.","Lower the bar to the starting position.","Repeat"]},{"slug":"upright-cable-row","title":"Upright Cable Row","idNum":"0015","type":"isolation","primary":["shoulders"],"secondary":["upper back","biceps"],"equipment":["cable machine"],"steps":["Attach a straight bar to the pulley on the floor.","Stand with your feet shoulder width apart, your abs drawn in and your back straight.","Grasp the bar with an overhand grasp (your palms facing downwards) and pull it up towards your waist, this is the starting position.","Raise the bar up to in line with your shoulders.","Pause at the top and rotate your shoulder blades together.","Lower the bar in a controlled motion to the starting position."]},{"slug":"v-bar-pull-down","title":"V Bar Pull Down","idNum":"0096","type":"isolation","primary":["lats"],"secondary":["middle back","biceps"],"equipment":["cable machine"],"steps":["Attach a V bar to the pull down pulley of a cable machine.","Sitting upright with your abs drawn grasp the bar with an overhand grip, your palms facing in.","Pull the bar straight down to your upper chest.","Pause for a moment after touching the chest and then slowly return the bar to starting position.","Repeat."]},{"slug":"walking-lunges","title":"Walking Lunges","idNum":"0121","type":"isolation","primary":["hamstrings"],"secondary":["quadriceps","gluts","calves"],"equipment":["barbell or dumbbell"],"steps":["Start by either placing a barbell across your upper back or by grasping a dumbbell in each hand.","Stand with your feet about 8 inches apart, toes facing forward.","Take a lunge forward keeping your abs drawn in and your upper body straight.","Slowly lower one knee down as if kneeling while keeping your other knee bent at a 90 degree angle, do not let your knee touch the ground.","Lower your body to just above the floor and hold for a moment before pushing off with the back foot.","Step through and repeat the exercise with the other leg."]},{"slug":"weighted-ball-side-bend","title":"Weighted Ball Side Bend","idNum":"0208","type":"isolation","primary":["obliques"],"secondary":[],"equipment":["weight","exercise ball"],"steps":["This exercise use a Stability Ball instead of a bench. The Stability Ball conforms better to your body and allows for correct anatomical range of movement.","Lie one side of your torso, and with your waist and hip against a Stability Ball, position your feet on the floor (or against a wall) for support.","With one hand, hold a weight against the side of your head.","Place your free hand across your chest to steady yourself.","Raise your torso up off the ball by flexing your waist.","With controlled movements lower yourself back onto the ball."]},{"slug":"weighted-sissy-squat-with-weight-plate","title":"Weighted Sissy Squat with Weight Plate","idNum":"0158","type":"isolation","primary":["quadriceps"],"secondary":[],"equipment":["weight plate"],"steps":["Don't let the name of this exercise fool you, it is a an assisted squat which effectively works the quadriceps (leg muscles).","Grasp a weight rack or bar for support with one arm and hold a free weight plate across your chest with your other hand.","With your abs drawn in, squat down lowering your body to the floor until your knees are almost fully flexed.","Return to the starting position.","Note: Keep your feet placed firmly on the floor throughout this exercise."]},{"slug":"wide-grip-bench-press","title":"Wide Grip Bench Press","idNum":"0082","type":"isolation","primary":["chest"],"secondary":["triceps","shoulders"],"equipment":["flat bench","barbell"],"steps":["Lie flat on a bench with your feet flat on the floor.","Place your hands wider than shoulder width apart on the bar and lift it off the rack, this is starting position.","Bring the bar over your chest and lower it till it is just above your body.","Extend your arms upward and raise the bar straight up.","Pause for a moment and with slow controlled movement, return the bar to starting position.","Repeat."]},{"slug":"wide-grip-chin-up","title":"Wide Grip Chin Up","idNum":"0091","type":null,"primary":["back"],"secondary":["neck","biceps"],"equipment":[],"steps":["Grasp a chin up bar with a slightly wider than shoulder width grip.","Keeping your body straight pull yourself up and to one side of the bar.","Lower your body back down to the starting position.","Raise yourself to the other side of the bar.","Repeat."]},{"slug":"wide-grip-decline-barbell-pullover","title":"Wide Grip Decline Barbell Pullover","idNum":"0064","type":"isolation","primary":["chest"],"secondary":[],"equipment":["decline bench","barbell"],"steps":["Lie on a decline bench with your feet higher than your head and your feet firmly on the ground.","Grasp the barbell with an extra wide grip (your hands near the plates) and starting at you’re your upper thighs raise the barbell in an arc over your head towards the floor.","Slowly return the barbell to starting position on your thighs.","Repeat."]},{"slug":"wide-grip-decline-bench-press","title":"Wide Grip Decline Bench Press","idNum":"0083","type":"isolation","primary":["chest"],"secondary":["triceps","shoulders"],"equipment":["barbell","decline bench"],"steps":["Lie on a decline bench with your head lower than your feet.","Place your hands wider than shoulder width apart on the bar and lift it off the rack.","Bring the bar over your chest and lower it till it is just above the lower portion of your chest, this is starting position.","Extend your arms upward and raise the bar straight up.","Pause for a moment and then lower the bar to starting position.","Repeat."]},{"slug":"wide-grip-standing-biceps-curl-with-barbell","title":"Wide Grip Standing Biceps Curl with Barbell","idNum":"0250","type":"isolation","primary":["biceps"],"secondary":["forearm"],"equipment":["barbell"],"steps":["This is a wide grip version of a biceps curl. The wider grip targets the lateral or outer portion of the muscle.","Stand with your feet shoulder width apart, your knees slightly bent and your abs drawn in.","Grasp a barbell with palms up as wide as you comfortably can.","Extend your arms fully against your thighs.","Keeping your elbows straight, raise the bar towards your chest until your forearms touch your chest.","Pause for moment and then return to the starting position.","Note: Lean up against a wall or post if you have problems keeping from swinging."]},{"slug":"wide-stance-squat-with-barbell","title":"Wide Stance Squat with Barbell","idNum":"0160","type":"compound","primary":["quadriceps"],"secondary":["calves","hamstrings"],"equipment":["barbell"],"steps":["Lifting a barbell off of a weight rack, position it on your shoulders.","Stand with your feet wider than shoulder width apart (about 30 inches apart) with your toes pointing out.","Drawing your abs in descend slowly by bending at the knees and hips as if you are sitting down (squatting).","Lower yourself as far as you can control without letting your body shift towards your toes (this will cause you to loose balance).","Pause in the downward position and slowly return upright to the starting position.","Note: A pad on the bar or towel on your shoulders can help improve your grip and reduce the discomfort of the bar against your back. Practice the squat without any weight to allow yourself to become comfortable with the movements."]},{"slug":"zecher-squats","title":"Zecher Squats","idNum":"0161","type":"compound","primary":["quadriceps"],"secondary":["glutes","hamstrings","calves"],"equipment":["barbell"],"steps":["This variation of squat is similar to a Front Squat, it works to build the upper muscles of the quadriceps (thighs).","Lift a barbell off of a weight rack and place across your chest. Hold the barbell with your arms crossed.","Place your feet slightly wider than shoulder width apart with your knees and toes pointed slightly outward.","Drawing your abs in, descend slowly by bending at the knees and hips as if you are sitting down (squatting).","Lower yourself as far as you can control without letting your body shift towards your toes (this will cause you to loose balance).","Pause in the downward position and slowly return upright to the starting position.","Note: Practice the squat without any weight to allow yourself to become comfortable with the movements."]},{"slug":"zottman-curl-with-dumbbells","title":"Zottman Curl with Dumbbells","idNum":"0251","type":"isolation","primary":["biceps"],"secondary":["forearm"],"equipment":["dumbbell"],"steps":["Stand with your feet shoulder width apart, your knees slightly bent and your and your abs drawn in.","Grasp a dumbbell in each hand with your palms facing each other.","Start with your hands at your sides.","Curl your arms up turning your wrists so they are facing down as the dumbbells reach your chest.","Pause for a moment and then return to the starting position."]},{"slug":"zottman-preacher-curl-with-dumbbells","title":"Zottman Preacher Curl with Dumbbells","idNum":"0252","type":"isolation","primary":["biceps"],"secondary":["forearm"],"equipment":["dumbbell"],"steps":["Sit at a Preacher Curl Bench.","Grasp a dumbbell in your hand with your palms facing up.","Extend your arm fully along the bench.","Curl your arm up turning your wrist so it faces down as the dumbbell reaches your chest.","Pause for a moment and then return to the starting position and switch arms."]}];

const CDN = "https://cdn.jsdelivr.net/gh/everkinetic/data@main/dist/svg";
/** Raw SVG (14–28KB each — used only as the onError fallback). */
export const illustrationUrl = (idNum: string, state: "tension" | "relaxation"): string =>
  `${CDN}/${idNum}-${state}.svg`;

/** Rasterized WebP via the image proxy — ~4KB at thumb size with CDN edge
 *  caching, so lists paint fast instead of downloading + rasterizing a
 *  20KB vector per row. */
export const illustrationImg = (idNum: string, state: "tension" | "relaxation", width: number): string =>
  `https://images.weserv.nl/?url=${encodeURIComponent(`cdn.jsdelivr.net/gh/everkinetic/data@main/dist/svg/${idNum}-${state}.svg`)}&w=${width}&output=webp&q=80`;

const norm = (s: string) => s.toLowerCase().replace(/[^a-z0-9]+/g, " ").trim();
let byNorm: Map<string, IllustratedExercise> | null = null;
export const findIllustrated = (name?: string | null): IllustratedExercise | null => {
  if (!name) return null;
  if (!byNorm) {
    byNorm = new Map();
    for (const e of ILLUSTRATED_EXERCISES) byNorm.set(norm(e.title), e);
  }
  return byNorm.get(norm(name)) ?? null;
};
export const normIllustratedName = norm;
